// tutorials-data.js — ServiceNow Developer Tutorial Content
// Batch 1: All topics expanded with GfG-style content
// Load before tutorials.html script via <script src="tutorials-data.js"></script>

var CATEGORIES = [
  // ═══════════════════════════════════════════════════════════════════════════
  // FOUNDATIONS
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"foundations",title:"Foundations",icon:"⬡",children:[
    {id:"platform-architecture",title:"Platform Architecture",difficulty:"beginner",time:"20 min",sections:[
      {type:"theory",title:"Multi-Instance Architecture",content:"ServiceNow uses a <strong>multi-instance</strong> architecture — each customer gets a dedicated instance with its own database, application server, and runtime resources.\n\nEvery instance comprises four layers working together to process requests:"},
      {type:"table",title:"Platform Layers",headers:["Layer","Components"],rows:[["UI Layer","Now Experience Framework (Web Components + GraphQL), Classic UI (Jelly + AngularJS 1.x)"],["Application Layer","Java, JavaScript, Glide scripting engine, Rhino JS engine"],["Platform Logic","Business Rules, ACLs, Flow Designer, Workflow engine, Event engine"],["Data Layer","MariaDB (OLTP), RaptorDB (PostgreSQL-based HTAP for analytics)"]]},
      {type:"theory",title:"Request Flow",content:"When a user interacts with ServiceNow:\n\n<strong>Client → Web Server → Application Server → Glide Engine → Business Rules / ACLs → Database → Response</strong>\n\nThe Glide engine is the core abstraction layer — it wraps database operations in JavaScript-friendly APIs like GlideRecord, GlideSystem, and GlideForm. You never write raw SQL."},
      {type:"theory",title:"MID Server",content:"The <strong>MID Server</strong> (Management, Instrumentation, and Discovery) is a Java application installed on your local network. It bridges your ServiceNow cloud instance and on-premise resources.\n\nCommunication flows through the <strong>ECC Queue</strong> — the MID Server polls for outbound work and writes results back. Only outbound HTTPS is needed."},
      {type:"code",title:"Verify Instance Info",code:"// Check your instance details using GlideSystem\ngs.info('Instance URL: ' + gs.getProperty('glide.servlet.uri'));\ngs.info('Current User: ' + gs.getUserName());\ngs.info('User ID (sys_id): ' + gs.getUserID());\ngs.info('Current Date/Time: ' + gs.nowDateTime());\ngs.info('Has admin role: ' + gs.hasRole('admin'));\ngs.info('Has itil role: ' + gs.hasRole('itil'));"},
      {type:"quiz",questions:[{q:"What type of architecture does ServiceNow use?",opts:["Multi-tenant","Multi-instance","Serverless","Peer-to-peer"],ans:1,exp:"ServiceNow uses multi-instance architecture where each customer gets a dedicated instance."},{q:"What does the Glide engine do?",opts:["Renders the UI","Translates JS API calls to SQL queries","Manages network traffic","Handles authentication only"],ans:1,exp:"The Glide engine wraps database operations into JavaScript-friendly APIs like GlideRecord."}]}
    ]},
    {id:"javascript-rhino",title:"JavaScript & Rhino Engine",difficulty:"beginner",time:"25 min",sections:[
      {type:"theory",title:"The Rhino Engine",content:"ServiceNow's server-side JavaScript runs on <strong>Mozilla Rhino</strong> — a Java-based JS engine. Your server scripts are compiled to Java bytecode at runtime.\n\nRhino doesn't support modern ES6+ natively. Newer releases have progressively added support:"},
      {type:"table",title:"Rhino by Release",headers:["Release","Rhino","Key Additions"],rows:[["Pre-Washington","~1.7R5","ES5 only (var, function, prototype)"],["Washington DC","1.7.12","Arrow functions, Array.includes()"],["Xanadu","1.7.14","Template literals"],["Tokyo+ (ES12)","Transpilation","let/const, class, optional chaining (scoped apps only)"]]},
      {type:"theory",title:"The #1 Gotcha: GlideElement vs String",content:"<code>gr.field</code> returns a <strong>GlideElement</strong> (Java→JS pointer), NOT a string. It changes when the cursor moves.\n\n<strong>Always use <code>getValue()</code> to extract actual values.</strong>\n\nPushing <code>gr.field</code> into an array inside <code>while(gr.next())</code> fills the entire array with the LAST record's values."},
      {type:"code",title:"GlideElement Gotcha Demo",code:"// ❌ WRONG — the classic GlideElement trap\nvar badArray = [];\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.setLimit(3);\ngr.query();\nwhile (gr.next()) {\n    badArray.push(gr.number);\n}\ngs.info('BAD array (all same): ' + badArray.join(', '));\n\n// ✅ CORRECT — use getValue()\nvar goodArray = [];\ngr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.setLimit(3);\ngr.query();\nwhile (gr.next()) {\n    goodArray.push(gr.getValue('number'));\n}\ngs.info('GOOD array (actual): ' + goodArray.join(', '));"},
      {type:"code",title:"Safe Patterns in ServiceNow",code:"var gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\n\nvar incidents = [];\nwhile (gr.next()) {\n    incidents.push({\n        number: gr.getValue('number'),\n        desc: gr.getValue('short_description'),\n        priority: gr.getValue('priority')\n    });\n}\n\nvar critical = incidents.filter(function(inc) {\n    return inc.priority === '1';\n});\n\ngs.info('Total active: ' + incidents.length);\ngs.info('Critical (P1): ' + critical.length);\ngs.info('P1 Numbers: ' + critical.map(function(i){return i.number}).join(', '));\ngs.info('JSON:\\n' + JSON.stringify(critical, null, 2));"},
      {type:"quiz",questions:[{q:"What does gr.field return?",opts:["A String","A Number","A GlideElement (Java→JS pointer)","An Object"],ans:2,exp:"gr.field returns a GlideElement. Always use getValue() for the actual string."},{q:"Which keyword for server-side variables?",opts:["let","const","var","auto"],ans:2,exp:"Use var for server-side. let/const only in scoped apps with ES12 mode."}]}
    ]},
    {id:"data-model",title:"Data Model & Tables",difficulty:"beginner",time:"15 min",sections:[
      {type:"theory",title:"Table Inheritance",content:"The <code>task</code> table is the foundation — <code>incident</code>, <code>problem</code>, <code>change_request</code> all <strong>extend</strong> it, inheriting every parent field.\n\nA query on <code>task</code> returns ALL child records. A query on <code>incident</code> returns only incidents."},
      {type:"theory",title:"sys_id: The Universal Key",content:"Every record has a <strong>sys_id</strong> — a 32-character GUID primary key.\n\n<strong>Never dot-walk to sys_id.</strong> The reference field already stores it — use <code>gr.getValue('caller_id')</code> instead of <code>gr.caller_id.sys_id</code>."},
      {type:"code",title:"Table Inheritance & Dot-Walking",code:"var gr = new GlideRecord('incident');\ngr.get('a1b2c3d4e5f6');\ngs.info('Incident: ' + gr.getValue('number'));\n\n// ✅ Reference field stores sys_id directly\nvar callerId = gr.getValue('caller_id');\ngs.info('Caller ID (efficient): ' + callerId);\n\nvar user = new GlideRecord('sys_user');\nif (user.get(callerId)) {\n    gs.info('Name: ' + user.getValue('first_name') + ' ' + user.getValue('last_name'));\n    gs.info('Email: ' + user.getValue('email'));\n    gs.info('VIP: ' + user.getValue('vip'));\n}"},
      {type:"quiz",questions:[{q:"Which table do incident, problem, change_request extend?",opts:["cmdb","sys_metadata","task","core_company"],ans:2,exp:"The task table is the base table. Incident, problem, and change_request extend it."}]}
    ]}
  ]},

  // ═══════════════════════════════════════════════════════════════════════════
  // CLIENT-SIDE DEVELOPMENT
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"client-side",title:"Client-Side",icon:"◧",children:[
    {id:"client-scripts",title:"Client Scripts",difficulty:"intermediate",time:"30 min",sections:[
      {type:"theory",title:"The Four Types",content:"Client Scripts run in the browser and manipulate form behavior:"},
      {type:"table",title:"Client Script Types",headers:["Type","Signature","Fires When","Key Gotcha"],rows:[["onLoad","function onLoad() { }","Form loads","Order unpredictable across scripts"],["onChange","onChange(ctrl, old, new, isLoading, isTemplate)","Field change + initial load","Must check isLoading"],["onSubmit","function onSubmit() { }","Form save/submit","Return false to block"],["onCellEdit","onCellEdit(sysIDs, table, old, new, cb)","List cell edits","Not a security mechanism"]]},
      {type:"theory",title:"Execution Order",content:"On form load: UI Policies FIRST → Client Scripts (onLoad) AFTER\n\nOn field change: Client Scripts (onChange) FIRST → UI Policies AFTER\n\n<strong>UI Policy wins on conflicts</strong> because it executes last."},
      {type:"code",title:"onChange with Guard Clause",code:"function onChange(control, oldValue, newValue, isLoading, isTemplate) {\n    if (isLoading || newValue === '') return;\n\n    if (newValue === '1') {\n        gs.info('[onChange] Priority set to P1 (Critical)');\n        gs.info('  → g_form.setMandatory(\"description\", true)');\n        gs.info('  → g_form.setMandatory(\"assignment_group\", true)');\n    } else {\n        gs.info('[onChange] Priority set to P' + newValue);\n        gs.info('  → Removing mandatory from description');\n    }\n}\n\ngs.info('--- Simulating priority → P1 ---');\nonChange('priority', '3', '1', false, false);\n\ngs.info('');\ngs.info('--- Simulating form load (should skip) ---');\nonChange('priority', '', '2', true, false);"},
      {type:"code",title:"onSubmit Validation Pattern",code:"function onSubmit() {\n    var shortDesc = current.getValue('short_description');\n    var priority = current.getValue('priority');\n    var errors = [];\n\n    if (gs.nil(shortDesc)) errors.push('Short Description required');\n\n    if (priority === '1') {\n        var desc = current.getValue('description');\n        if (gs.nil(desc) || desc.length < 20)\n            errors.push('P1 needs detailed description (20+ chars)');\n    }\n\n    if (errors.length > 0) {\n        errors.forEach(function(e) { gs.error('  ✗ ' + e); });\n        gs.info('→ Form BLOCKED (return false)');\n        return false;\n    }\n    gs.info('✓ All passed — form submits');\n    return true;\n}\n\ngs.info('--- Test: Valid incident ---');\nonSubmit();"},
      {type:"quiz",questions:[{q:"Execution order on form load?",opts:["Client Scripts first","UI Policies first","Simultaneous","Depends on order field"],ans:1,exp:"UI Policies execute FIRST, then Client Scripts (onLoad)."},{q:"Why check isLoading in onChange?",opts:["Performance","onChange fires on form load too","Prevent infinite loops","Security"],ans:1,exp:"onChange fires during initial form load. isLoading check prevents logic from running during load."}]}
    ]},
    {id:"glide-form",title:"GlideForm (g_form) API",difficulty:"intermediate",time:"25 min",sections:[
      {type:"theory",title:"Complete g_form Reference",content:"The <strong>g_form</strong> object is the primary client-side API for form manipulation. Available in Client Scripts, UI Policies, and UI Actions. No constructor needed — it's a global object.\n\nOrganized into six method categories:"},
      {type:"table",title:"g_form Methods by Category",headers:["Category","Key Methods"],rows:[
        ["Field Values","getValue(field), setValue(field, value [, displayValue]), clearValue(field), getDisplayValue(field), getBooleanValue(field)"],
        ["Field Display","setVisible(field, bool), setDisplay(field, bool), setReadOnly(field, bool), setMandatory(field, bool), setLabel(field, label)"],
        ["Choice Lists","addOption(field, value, label [, index]), removeOption(field, value), clearOptions(field)"],
        ["References","getReference(field, callback) — ALWAYS use async callback"],
        ["Messages","showFieldMsg(field, msg, type), hideFieldMsg(field), addInfoMessage(msg), addErrorMessage(msg), clearMessages()"],
        ["Decorations","addDecoration(field, icon, title), removeDecoration(field, icon, title)"],
        ["Sections","setSectionDisplay(section, bool), getSectionNames(), isSectionVisible(section)"],
        ["Utilities","isNewRecord(), save(), submit(), getTableName(), getUniqueValue(), flash(field, color, count)"]
      ]},
      {type:"theory",title:"The setValue Gotcha",content:"<strong>Critical</strong>: <code>setValue()</code> on a <strong>reference field</strong> without the 3rd parameter triggers a <strong>synchronous server call</strong> to resolve the display value, freezing the UI.\n\n<code>g_form.setValue('caller_id', 'sys_id_here')</code> ← ❌ Sync call, UI freeze\n<code>g_form.setValue('caller_id', 'sys_id_here', 'John Doe')</code> ← ✅ No server call"},
      {type:"theory",title:"setVisible vs setDisplay",content:"Both hide fields but behave differently:\n\n<code>setVisible(field, false)</code> — hides the field but <strong>keeps the space</strong> (blank row on form)\n<code>setDisplay(field, false)</code> — hides the field AND <strong>collapses the space</strong>\n\nAlmost always use <code>setDisplay()</code> unless you need the layout to stay stable."},
      {type:"code",title:"g_form Method Patterns",code:"// Simulating common g_form patterns\n// In real ServiceNow, g_form is available globally in Client Scripts\n\ngs.info('=== getValue / setValue ===');\ngs.info('Current priority: ' + current.getValue('priority'));\ngs.info('Current category: ' + current.getValue('category'));\n\ngs.info('');\ngs.info('=== Mandatory / ReadOnly ===');\ngs.info('g_form.setMandatory(\"description\", true)');\ngs.info('g_form.setReadOnly(\"category\", true)');\ngs.info('g_form.setLabel(\"short_description\", \"Issue Summary\")');\n\ngs.info('');\ngs.info('=== Choice manipulation ===');\ngs.info('g_form.addOption(\"priority\", \"0\", \"0 - Emergency\")');\ngs.info('g_form.removeOption(\"priority\", \"4\")');\n\ngs.info('');\ngs.info('=== Messages ===');\ngs.info('g_form.addInfoMessage(\"VIP caller detected\")');\ngs.info('g_form.showFieldMsg(\"caller_id\", \"This is a VIP\", \"info\")');\ngs.info('g_form.addErrorMessage(\"Missing required fields\")');\n\ngs.info('');\ngs.info('=== getReference (async pattern) ===');\ngs.info('g_form.getReference(\"caller_id\", function(ref) {');\ngs.info('    // ref.email, ref.vip, ref.name available here');\ngs.info('    // NEVER use synchronous: var ref = g_form.getReference(\"caller_id\")');\ngs.info('});');"},
      {type:"code",title:"Real-World: Dynamic Form Based on Category",code:"// onChange Client Script: Adjust form when category changes\nfunction onCategoryChange(newValue) {\n    gs.info('Category changed to: ' + newValue);\n    \n    // Reset form state\n    gs.info('→ g_form.setMandatory(\"cmdb_ci\", false)');\n    gs.info('→ g_form.setDisplay(\"u_vendor\", false)');\n    gs.info('→ g_form.setDisplay(\"u_building\", false)');\n    \n    switch(newValue) {\n        case 'hardware':\n            gs.info('→ g_form.setMandatory(\"cmdb_ci\", true)');\n            gs.info('→ g_form.setDisplay(\"u_vendor\", true)');\n            gs.info('→ g_form.showFieldMsg(\"cmdb_ci\", \"Select the affected CI\", \"info\")');\n            break;\n        case 'software':\n            gs.info('→ g_form.setMandatory(\"cmdb_ci\", true)');\n            gs.info('→ g_form.addInfoMessage(\"Check Known Errors before creating\")');\n            break;\n        case 'network':\n            gs.info('→ g_form.setDisplay(\"u_building\", true)');\n            gs.info('→ g_form.setMandatory(\"u_building\", true)');\n            break;\n        default:\n            gs.info('→ Standard form layout');\n    }\n}\n\ngs.info('--- Hardware selected ---');\nonCategoryChange('hardware');\ngs.info('');\ngs.info('--- Network selected ---');\nonCategoryChange('network');"},
      {type:"quiz",questions:[{q:"What happens calling setValue on a reference field without display value?",opts:["Nothing special","Synchronous server call (UI freeze)","Error thrown","Field clears"],ans:1,exp:"Without the 3rd parameter, ServiceNow makes a synchronous server call to resolve the display value."},{q:"Difference between setVisible and setDisplay?",opts:["No difference","setVisible keeps space, setDisplay collapses it","setDisplay is deprecated","setVisible only works on reference fields"],ans:1,exp:"setVisible hides but keeps blank space. setDisplay hides AND collapses the row."},{q:"How should you use getReference?",opts:["var ref = g_form.getReference('field')","g_form.getReference('field', callback)","g_form.getValue('field').getReference()","gs.getReference('field')"],ans:1,exp:"Always use the async callback pattern. The synchronous form triggers a blocking server call."}]}
    ]},
    {id:"glide-user",title:"GlideUser (g_user) API",difficulty:"beginner",time:"12 min",sections:[
      {type:"theory",title:"Client-Side User Context",content:"The <strong>g_user</strong> object provides information about the currently logged-in user. Available in all client-side scripts without initialization.\n\nKey distinction: <code>hasRole()</code> returns true for admin regardless of the role checked. Use <code>hasRoleExactly()</code> when you need to check a specific role without admin override."},
      {type:"table",title:"g_user Properties & Methods",headers:["Member","Returns","Notes"],rows:[
        ["userName","string","Login username (e.g., 'john.doe')"],
        ["userID","string","sys_id of the current user"],
        ["firstName","string","First name"],
        ["lastName","string","Last name"],
        ["hasRole('role')","boolean","admin always returns true"],
        ["hasRoleExactly('role')","boolean","admin does NOT auto-pass"],
        ["hasRoleFromList('r1,r2')","boolean","True if user has ANY role in comma-separated list"],
        ["getClientData('key')","string","Reads data set by session.putClientData on server"]
      ]},
      {type:"code",title:"g_user in Practice",code:"// g_user is available globally in Client Scripts\ngs.info('=== Current User Info ===');\ngs.info('Username: ' + gs.getUserName());\ngs.info('User ID: ' + gs.getUserID());\ngs.info('');\n\n// Role checking patterns\ngs.info('=== Role Checks ===');\ngs.info('hasRole(\"admin\"): ' + gs.hasRole('admin'));\ngs.info('hasRole(\"itil\"): ' + gs.hasRole('itil'));\ngs.info('');\n\n// Real-world: Control form based on role\nfunction setupFormByRole() {\n    var isAdmin = gs.hasRole('admin');\n    var isItil = gs.hasRole('itil');\n    \n    if (isAdmin) {\n        gs.info('Admin user — full form access');\n        gs.info('→ All fields editable');\n    } else if (isItil) {\n        gs.info('ITIL user — standard access');\n        gs.info('→ g_form.setReadOnly(\"assignment_group\", false)');\n        gs.info('→ g_form.setDisplay(\"u_internal_notes\", true)');\n    } else {\n        gs.info('End user — restricted view');\n        gs.info('→ g_form.setReadOnly(\"priority\", true)');\n        gs.info('→ g_form.setDisplay(\"assignment_group\", false)');\n    }\n}\n\nsetupFormByRole();"},
      {type:"quiz",questions:[{q:"g_user.hasRole('itil') returns true for admin users. How to check exact role?",opts:["g_user.hasRole('itil')","g_user.hasRoleExactly('itil')","g_user.checkRole('itil')","gs.hasExactRole('itil')"],ans:1,exp:"hasRoleExactly() checks the specific role without admin auto-pass."}]}
    ]},
    {id:"glide-ajax",title:"GlideAjax Pattern",difficulty:"advanced",time:"25 min",sections:[
      {type:"theory",title:"Client-to-Server Communication",content:"<strong>GlideAjax</strong> bridges client and server code. The pattern requires TWO components:\n\n1. <strong>Client Script</strong>: Creates GlideAjax instance, sets parameters, calls getXMLAnswer\n2. <strong>Script Include</strong>: Extends AbstractAjaxProcessor, returns data\n\nFar more efficient than synchronous GlideRecord calls from the client."},
      {type:"code",title:"Complete GlideAjax Flow",code:"var IncidentUtils = {\n    getCallerInfo: function(userId) {\n        var gr = new GlideRecord('sys_user');\n        if (gr.get(userId)) {\n            return JSON.stringify({\n                name: gr.getValue('first_name') + ' ' + gr.getValue('last_name'),\n                email: gr.getValue('email'),\n                vip: gr.getValue('vip'),\n                title: gr.getValue('title')\n            });\n        }\n        return JSON.stringify({ error: 'User not found' });\n    }\n};\n\ngs.info('=== GlideAjax Flow ===');\ngs.info('');\ngs.info('1. [CLIENT] GlideAjax(\"IncidentUtils\")');\ngs.info('   → sysparm_name: \"getCallerInfo\"');\ngs.info('   → sysparm_user_id: \"u001\"');\n\nvar response = IncidentUtils.getCallerInfo('u001');\ngs.info('');\ngs.info('2. [SERVER] Executing...');\ngs.info('   → Result: ' + response);\n\nvar data = JSON.parse(response);\ngs.info('');\ngs.info('3. [CLIENT] Callback:');\ngs.info('   → Name: ' + data.name);\ngs.info('   → VIP: ' + data.vip);\nif (data.vip === 'true') gs.info('   → Auto-setting P1');"},
      {type:"quiz",questions:[{q:"What must a Script Include extend for GlideAjax?",opts:["GlideRecord","AbstractAjaxProcessor","ScriptInclude","ClientCallable"],ans:1,exp:"Must extend AbstractAjaxProcessor with Client callable checked."},{q:"Which parameter is mandatory?",opts:["sysparm_value","sysparm_name","sysparm_table","sysparm_query"],ans:1,exp:"sysparm_name tells the server which method to call."}]}
    ]},
    {id:"ui-policies",title:"UI Policies",difficulty:"beginner",time:"18 min",sections:[
      {type:"theory",title:"Declarative Form Control",content:"UI Policies provide <strong>no-code form control</strong> — show/hide fields, make fields mandatory or read-only, all without writing JavaScript.\n\nThey consist of <strong>conditions</strong> (when to trigger) and <strong>actions</strong> (what to do). The key feature is <strong>Reverse if false</strong> — when the condition is no longer met, the actions automatically undo."},
      {type:"theory",title:"When to Use UI Policies vs Client Scripts",content:"<strong>Use UI Policies when:</strong>\n• You need simple show/hide/mandatory/read-only logic\n• You want automatic reversal when conditions change\n• The logic is purely declarative (no calculations, no server calls)\n\n<strong>Use Client Scripts when:</strong>\n• You need onSubmit validation\n• You need GlideAjax server lookups\n• You need access to oldValue in onChange\n• Logic involves complex multi-step calculations\n• You need onCellEdit behavior"},
      {type:"table",title:"UI Policy vs Client Script",headers:["Feature","UI Policy","Client Script"],rows:[
        ["Code required","No","Yes"],
        ["Reverse if false","Built-in","Manual"],
        ["Execution order","After Client Scripts (wins conflicts)","Before UI Policies"],
        ["onSubmit validation","No","Yes"],
        ["Server calls (GlideAjax)","No","Yes"],
        ["Access to oldValue","No","Yes (onChange)"],
        ["Service Portal support","Yes","Yes (with limitations)"]
      ]},
      {type:"code",title:"Simulating UI Policy Behavior",code:"// UI Policy: When priority is P1, make description mandatory\n// Condition: priority == 1\n// Actions: description → Mandatory = true\n// Reverse if false: Yes\n\nfunction simulateUIPolicy(priority) {\n    gs.info('Priority set to: P' + priority);\n    \n    // Condition check\n    if (priority === '1') {\n        gs.info('→ [UI Policy] Condition MET (priority == 1)');\n        gs.info('  → description: Mandatory = true');\n        gs.info('  → assignment_group: Mandatory = true');\n        gs.info('  → impact: Visible = true');\n    } else {\n        // Reverse if false — automatic!\n        gs.info('→ [UI Policy] Condition NOT met — REVERSING');\n        gs.info('  → description: Mandatory = false');\n        gs.info('  → assignment_group: Mandatory = false');\n        gs.info('  → impact: Visible = false (reversed)');\n    }\n}\n\ngs.info('=== UI Policy Simulation ===');\ngs.info('');\nsimulateUIPolicy('1');\ngs.info('');\nsimulateUIPolicy('3');"},
      {type:"quiz",questions:[{q:"What is 'Reverse if false' in UI Policies?",opts:["Deletes the policy when condition fails","Auto-undoes actions when condition no longer met","Reverses the form layout","Triggers a reverse Business Rule"],ans:1,exp:"Reverse if false automatically undoes the UI Policy actions when the condition is no longer met."},{q:"If both a Client Script and UI Policy set the same field, which wins?",opts:["Client Script","UI Policy","Last one executed","First one executed"],ans:1,exp:"UI Policies execute after Client Scripts, so they override any conflicting changes."}]}
    ]},
    {id:"service-portal",title:"Service Portal Widgets",difficulty:"advanced",time:"30 min",sections:[
      {type:"theory",title:"Widget Architecture",content:"Service Portal widgets are self-contained components built on <strong>AngularJS 1.x</strong>. Each widget has four parts:\n\n1. <strong>HTML Template</strong> — AngularJS bindings with <code>{{c.data.property}}</code>\n2. <strong>Client Script</strong> — Controller with <code>$scope</code> and <code>c.data</code>\n3. <strong>Server Script</strong> — Populates the <code>data</code> object (runs on page load and on <code>c.server.update()</code>)\n4. <strong>CSS/SCSS</strong> — Scoped styles for the widget\n\nData flows: Server Script populates <code>data</code> → Client receives <code>c.data</code> → <code>c.server.update()</code> sends data back to server."},
      {type:"theory",title:"Portal g_form Subset",content:"The portal provides a <strong>subset</strong> of the Classic UI g_form API. Key differences:\n\n• <code>addDecoration()</code> — NOT available in portal\n• <code>flash()</code> — NOT available in portal\n• <code>getReference()</code> — works but uses different async pattern\n• <code>showFieldMsg()</code> — works differently, no scroll-to behavior\n• UI Actions — only server-side execute in portal\n\nAlways test your Client Scripts in Service Portal separately — they may not behave identically to Classic UI."},
      {type:"code",title:"Widget Server-Client Data Flow",code:"// === SERVER SCRIPT (runs on load + c.server.update()) ===\nfunction serverScript() {\n    var data = {};\n    \n    // Query incidents for current user\n    var gr = new GlideRecord('incident');\n    gr.addQuery('caller_id', gs.getUserID());\n    gr.addQuery('active', 'true');\n    gr.orderByDesc('sys_created_on');\n    gr.setLimit(5);\n    gr.query();\n    \n    data.incidents = [];\n    while (gr.next()) {\n        data.incidents.push({\n            number: gr.getValue('number'),\n            short_description: gr.getValue('short_description'),\n            state: gr.getValue('state'),\n            priority: gr.getValue('priority')\n        });\n    }\n    data.count = data.incidents.length;\n    return data;\n}\n\nvar result = serverScript();\ngs.info('=== Widget Server Script Output ===');\ngs.info('Incidents found: ' + result.count);\nresult.incidents.forEach(function(inc) {\n    gs.info('  ' + inc.number + ' [P' + inc.priority + '] ' + inc.short_description);\n});\n\ngs.info('');\ngs.info('=== HTML Template would use: ===');\ngs.info('  <div ng-repeat=\"inc in c.data.incidents\">');\ngs.info('    {{inc.number}} — {{inc.short_description}}');\ngs.info('  </div>');"},
      {type:"quiz",questions:[{q:"What populates c.data in a Service Portal widget?",opts:["Client Script","HTML template","Server Script","CSS"],ans:2,exp:"The Server Script populates the data object, accessible as c.data in the client."},{q:"How does a widget send data back to the server?",opts:["g_form.submit()","c.server.update()","$http.post()","GlideAjax"],ans:1,exp:"c.server.update() sends the current data object back to the Server Script for processing."}]}
    ]},
    {id:"ui-builder",title:"UI Builder & Now Experience",difficulty:"advanced",time:"25 min",sections:[
      {type:"theory",title:"The Seismic Framework",content:"UI Builder is ServiceNow's modern low-code interface designer, built on the <strong>Seismic Framework</strong> (Web Components with Shadow DOM).\n\nKey differences from Service Portal:\n\n• <strong>No AngularJS</strong> — uses native Web Components\n• <strong>GraphQL</strong> replaces XML/AJAX for server communication\n• <strong>Declarative actions</strong> instead of imperative scripting\n• <strong>Workspace-focused</strong> design for agent experiences\n• Components are <strong>isolated</strong> via Shadow DOM (no CSS bleed)"},
      {type:"table",title:"Service Portal vs UI Builder",headers:["Aspect","Service Portal","UI Builder"],rows:[
        ["Framework","AngularJS 1.x","Web Components (Seismic)"],
        ["Communication","REST / GlideAjax","GraphQL"],
        ["Styling","Global CSS/SCSS","Shadow DOM (isolated)"],
        ["Data binding","AngularJS {{}} / $scope","Declarative properties"],
        ["Use case","Self-service portals","Agent workspaces"],
        ["Custom code","Widget Client/Server Scripts","Custom components (Now CLI)"],
        ["Future direction","Maintained, not primary","Primary investment"]
      ]},
      {type:"theory",title:"When to Use Which",content:"<strong>Use Service Portal</strong> for customer/employee-facing self-service portals, catalog experiences, and knowledge bases.\n\n<strong>Use UI Builder</strong> for agent workspaces, configurable dashboards, and any new internal tooling. ServiceNow's investment is clearly in UI Builder / Now Experience going forward."},
      {type:"quiz",questions:[{q:"What replaced AngularJS in Now Experience?",opts:["React","Vue.js","Web Components (Seismic)","Svelte"],ans:2,exp:"Now Experience uses the Seismic Framework built on native Web Components with Shadow DOM."},{q:"What protocol does UI Builder use for server communication?",opts:["REST","SOAP","GlideAjax","GraphQL"],ans:3,exp:"UI Builder uses GraphQL instead of the traditional REST/GlideAjax pattern."}]}
    ]}
  ]},

  // ═══════════════════════════════════════════════════════════════════════════
  // SERVER-SIDE DEVELOPMENT
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"server-side",title:"Server-Side",icon:"⬢",children:[
    {id:"business-rules",title:"Business Rules",difficulty:"intermediate",time:"35 min",sections:[
      {type:"theory",title:"The Five Types",content:"Business Rules are server-side scripts that execute when records are displayed, inserted, updated, or deleted."},
      {type:"table",title:"Business Rule Types",headers:["Type","When","Use For","Constraint"],rows:[["Before","Before DB write","Modify current, validation","current writable; previous available"],["After","After DB write","Events, update related records","current read-only intent"],["Async","Queued after commit","Long operations, API calls","previous is NULL"],["Display","On form load","Populate g_scratchpad","Only existing records"],["Before Query","Before DB query","Restrict visible records","No security message"]]},
      {type:"theory",title:"Order & Weight",content:"<strong>order</strong> field (default 100, lower = first) determines sequence. <strong>weight</strong> (0–3) is secondary.\n\nCritical threshold: <strong>order 1000</strong> — Approval Engine, Assignment Rules, Data Policies fire here."},
      {type:"code",title:"Before BR: Auto-Assign VIP",code:"gs.info('=== Before BR: Auto-Assign VIP ===');\n\nvar callerId = current.getValue('caller_id');\nvar caller = new GlideRecord('sys_user');\n\nif (caller.get(callerId)) {\n    gs.info('Caller: ' + caller.getValue('first_name') + ' ' + caller.getValue('last_name'));\n    gs.info('VIP: ' + caller.getValue('vip'));\n    \n    if (caller.getValue('vip') === 'true') {\n        gs.info('');\n        gs.info('⚡ VIP — auto-escalation:');\n        current.setValue('priority', '1');\n        gs.info('  → Priority: P1');\n        current.setValue('assigned_to', 'u002');\n        gs.info('  → Assigned to: Jane Smith');\n        gs.eventQueue('incident.vip.created', current,\n            caller.getValue('email'), current.getValue('number'));\n    } else {\n        gs.info('Standard caller');\n    }\n}"},
      {type:"code",title:"Preventing Infinite Loops",code:"gs.info('=== Anti-Recursion Patterns ===');\n\n// Pattern 1: Check actual change\nvar curState = current.getValue('state');\nvar prevState = previous.getValue('state');\ngs.info('Current: ' + curState + ' | Previous: ' + prevState);\nif (curState !== prevState) {\n    gs.info('✓ State changed — proceed');\n} else {\n    gs.info('✗ Unchanged — SKIP');\n}\n\ngs.info('');\n\n// Pattern 2: setWorkflow(false)\nvar gr = new GlideRecord('incident');\ngr.get('a1b2c3d4e5f6');\ngr.setValue('description', 'Updated by automation');\ngr.setWorkflow(false);\ngr.autoSysFields(false);\ngr.update();\ngs.info('Updated silently — no BRs triggered');"},
      {type:"quiz",questions:[{q:"'previous' in Async BR?",opts:["Previous version","null","Same as current","Empty GlideRecord"],ans:1,exp:"In Async BRs, previous is NULL."},{q:"At what order do engines fire?",opts:["100","500","1000","After all BRs"],ans:2,exp:"Engines fire at order 1000."}]}
    ]},
    {id:"script-includes",title:"Script Includes",difficulty:"intermediate",time:"25 min",sections:[
      {type:"theory",title:"Three Patterns",content:"Script Includes load <strong>on-demand</strong> — only when called:\n\n1. <strong>Standard Class</strong>: Class.create() with prototype\n2. <strong>AbstractAjaxProcessor</strong>: Client-callable (GlideAjax)\n3. <strong>Classless Function</strong>: For conditions"},
      {type:"code",title:"Standard Class Pattern",code:"var IncidentHelper = {\n    getActiveP1Count: function() {\n        var ga = new GlideAggregate('incident');\n        ga.addQuery('active', 'true');\n        ga.addQuery('priority', '1');\n        ga.addAggregate('COUNT');\n        ga.query();\n        if (ga.next()) return parseInt(ga.getAggregate('COUNT'));\n        return 0;\n    },\n    getAssignedIncidents: function(userId) {\n        var results = [];\n        var gr = new GlideRecord('incident');\n        gr.addQuery('assigned_to', userId);\n        gr.addQuery('active', 'true');\n        gr.orderBy('priority');\n        gr.query();\n        while (gr.next()) {\n            results.push({\n                number: gr.getValue('number'),\n                priority: 'P' + gr.getValue('priority'),\n                desc: gr.getValue('short_description')\n            });\n        }\n        return results;\n    }\n};\n\ngs.info('Active P1: ' + IncidentHelper.getActiveP1Count());\nvar list = IncidentHelper.getAssignedIncidents('u002');\ngs.info('\\nJane\\'s incidents:');\nlist.forEach(function(inc) {\n    gs.info('  ' + inc.number + ' [' + inc.priority + '] ' + inc.desc);\n});"},
      {type:"quiz",questions:[{q:"When do Script Includes load?",opts:["On instance boot","When the form loads","On-demand when called","Every transaction"],ans:2,exp:"Script Includes load on-demand, only when explicitly called."}]}
    ]},
    {id:"gliderecord-deep",title:"GlideRecord Deep Dive",difficulty:"intermediate",time:"40 min",sections:[
      {type:"theory",title:"Under the Hood",content:"GlideRecord translates to SQL: <code>addQuery('active', true)</code> → <code>WHERE active = 1</code>.\n\nDot-walking generates implicit JOINs. Invalid field names are <strong>silently ignored</strong>, returning the ENTIRE table."},
      {type:"code",title:"Complete CRUD",code:"gs.info('=== READ: Active P1/P2 ===');\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.addQuery('priority', '<=', '2');\ngr.orderBy('priority');\ngr.query();\nwhile (gr.next()) {\n    gs.info(gr.getValue('number') + ' [P' + gr.getValue('priority') + '] ' + gr.getValue('short_description'));\n}\n\ngs.info('');\ngs.info('=== CREATE ===');\nvar n = new GlideRecord('incident');\nn.initialize();\nn.setValue('short_description', 'Printer not responding');\nn.setValue('priority', '3');\nvar id = n.insert();\ngs.info('Created: ' + id);\n\ngs.info('');\ngs.info('=== AGGREGATE ===');\nvar ga = new GlideAggregate('incident');\nga.addQuery('active', 'true');\nga.addAggregate('COUNT');\nga.query();\nif (ga.next()) gs.info('Active count: ' + ga.getAggregate('COUNT'));"},
      {type:"code",title:"Performance: Array Flattening",code:"// ❌ Nested GlideRecords (N+1 problem)\ngs.info('=== ❌ Nested GlideRecords ===');\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nvar qCount = 0;\nwhile (gr.next()) {\n    var u = new GlideRecord('sys_user');\n    u.get(gr.getValue('caller_id'));\n    qCount++;\n}\ngs.info('Queries: ' + (qCount+1) + ' total');\ngs.warn('10K incidents = 10,001 queries!');\n\ngs.info('');\n\n// ✅ Array Flattening (always 2 queries)\ngs.info('=== ✅ Array Flattening ===');\nvar incs = [], ids = [];\ngr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nwhile (gr.next()) {\n    var cid = gr.getValue('caller_id');\n    incs.push({num: gr.getValue('number'), cid: cid});\n    if (ids.indexOf(cid) === -1 && cid) ids.push(cid);\n}\nvar map = {};\nvar ug = new GlideRecord('sys_user');\nug.addQuery('sys_id', 'IN', ids.join(','));\nug.query();\nwhile (ug.next()) map[ug.getValue('sys_id')] = ug.getValue('first_name') + ' ' + ug.getValue('last_name');\n\ngs.info('Queries: 2 total');\nincs.forEach(function(i) { gs.info('  ' + i.num + ' → ' + (map[i.cid]||'Unknown')); });"},
      {type:"quiz",questions:[{q:"Invalid field names in addQuery?",opts:["Error thrown","No records","Silently ignored — ALL records return","Timeout"],ans:2,exp:"Invalid fields are silently ignored, returning the ENTIRE table."},{q:"Efficient counting?",opts:["getRowCount()","GlideAggregate COUNT","Loop counter","getTableSize()"],ans:1,exp:"GlideAggregate counts at database level."}]}
    ]},
    {id:"glidesystem",title:"GlideSystem (gs) API",difficulty:"beginner",time:"20 min",sections:[
      {type:"theory",title:"The System Utility Object",content:"<code>gs</code> (GlideSystem) is the Swiss Army knife of server-side scripting. Available in every server script — Business Rules, Script Includes, Scheduled Jobs, Fix Scripts.\n\nNo initialization needed. Just call <code>gs.methodName()</code>."},
      {type:"table",title:"gs Methods by Category",headers:["Category","Methods"],rows:[
        ["Logging","gs.info(msg), gs.warn(msg), gs.error(msg), gs.debug(msg)"],
        ["User Context","gs.getUserID(), gs.getUserName(), gs.getUser(), gs.hasRole(role)"],
        ["Properties","gs.getProperty(name), gs.setProperty(name, value)"],
        ["Events","gs.eventQueue(name, record, parm1, parm2)"],
        ["Date/Time","gs.now(), gs.nowDateTime(), gs.beginningOfLastMonth()"],
        ["Null Check","gs.nil(value) — true if null, undefined, or empty string"],
        ["UI Messages","gs.addInfoMessage(msg), gs.addErrorMessage(msg)"],
        ["Utilities","gs.generateGUID(), gs.include(scriptInclude), gs.tableExists(table)"]
      ]},
      {type:"code",title:"gs Methods in Action",code:"// === Logging ===\ngs.info('This is informational');\ngs.warn('This is a warning');\ngs.error('This is an error');\ngs.debug('This only shows with debug enabled');\n\n// === User Context ===\ngs.info('');\ngs.info('=== User Context ===');\ngs.info('User: ' + gs.getUserName());\ngs.info('User ID: ' + gs.getUserID());\ngs.info('Is admin: ' + gs.hasRole('admin'));\ngs.info('Is ITIL: ' + gs.hasRole('itil'));\n\n// === Properties ===\ngs.info('');\ngs.info('=== Properties ===');\ngs.info('Instance URL: ' + gs.getProperty('glide.servlet.uri'));\n\n// === Null checking with gs.nil() ===\ngs.info('');\ngs.info('=== gs.nil() checks ===');\ngs.info('gs.nil(null): ' + gs.nil(null));\ngs.info('gs.nil(undefined): ' + gs.nil(undefined));\ngs.info('gs.nil(\"\"): ' + gs.nil(''));\ngs.info('gs.nil(\"hello\"): ' + gs.nil('hello'));\ngs.info('gs.nil(0): ' + gs.nil(0));\n\n// === Events ===\ngs.info('');\ngs.info('=== Event Queue ===');\ngs.eventQueue('incident.escalated', current, 'admin@example.com', 'INC0010001');\n\n// === Date/Time ===\ngs.info('');\ngs.info('=== Date/Time ===');\ngs.info('Today: ' + gs.now());\ngs.info('Now: ' + gs.nowDateTime());\n\n// === GUID ===\ngs.info('');\ngs.info('Generated GUID: ' + gs.generateGUID());"},
      {type:"quiz",questions:[{q:"What does gs.nil() return true for?",opts:["Only null","null and undefined","null, undefined, and empty string","All falsy values including 0"],ans:2,exp:"gs.nil() returns true for null, undefined, and empty string — but NOT for 0 or false."},{q:"Which gs method fires an asynchronous event?",opts:["gs.include()","gs.eventQueue()","gs.addInfoMessage()","gs.generateGUID()"],ans:1,exp:"gs.eventQueue() inserts a record into the sysevent table for asynchronous processing."}]}
    ]},
    {id:"scheduled-jobs",title:"Scheduled Jobs",difficulty:"intermediate",time:"18 min",sections:[
      {type:"theory",title:"Automated Script Execution",content:"Scheduled Jobs execute server-side scripts on a defined schedule. Three main types:\n\n<strong>Scheduled Script Executions</strong> — Custom scripts run on a schedule\n<strong>Scheduled Reports</strong> — Auto-generate and email reports\n<strong>Scheduled Imports</strong> — Pull data from external sources\n\nAll run as the <strong>system user</strong> context (not a specific user). They consume <strong>Scheduled Worker threads</strong> — long-running scripts can starve other scheduled work."},
      {type:"table",title:"Schedule Options",headers:["Type","Example","Use When"],rows:[
        ["Daily","Every day at 2:00 AM","Cleanup, daily reports"],
        ["Weekly","Every Monday at 6:00 AM","Weekly summaries"],
        ["Monthly","1st of month at midnight","Monthly audits"],
        ["Periodically","Every 15 minutes","Near-real-time sync"],
        ["Once","March 20 at 5:00 PM","One-time data fix"],
        ["On Demand","Manual trigger only","Ad-hoc maintenance"],
        ["Cron","0 */4 * * *","Complex schedules"]
      ]},
      {type:"code",title:"Scheduled Job: Stale Incident Cleanup",code:"// Scheduled Script Execution: Close stale resolved incidents\n// Schedule: Daily at 2:00 AM\n// Run as: System\n\ngs.info('=== Stale Incident Cleanup Job ===');\ngs.info('Running at: ' + gs.nowDateTime());\ngs.info('');\n\nvar gr = new GlideRecord('incident');\ngr.addQuery('state', '6'); // Resolved\ngr.addQuery('active', 'true');\n// In production: gr.addQuery('resolved_at', '<', gs.daysAgo(7));\ngr.query();\n\nvar count = 0;\nwhile (gr.next()) {\n    gs.info('Closing: ' + gr.getValue('number') + ' — ' + gr.getValue('short_description'));\n    gr.setValue('state', '7'); // Closed\n    gr.setValue('close_code', 'Closed/Resolved by Caller');\n    gr.setValue('close_notes', 'Auto-closed: resolved for 7+ days');\n    gr.setWorkflow(false); // Don't trigger BRs\n    gr.autoSysFields(false);\n    gr.update();\n    count++;\n}\n\ngs.info('');\ngs.info('Total closed: ' + count);\n\n// Best practice: Always setLimit() for safety during testing\n// gr.setLimit(10); // Test with small batch first"},
      {type:"quiz",questions:[{q:"What context do Scheduled Jobs run as?",opts:["Current user","Admin","System user","Service account"],ans:2,exp:"Scheduled Jobs run as the system user context, not a specific user."},{q:"What do long-running scheduled jobs consume?",opts:["Memory only","CPU only","Scheduled Worker threads","Database connections"],ans:2,exp:"They consume Scheduled Worker threads — long scripts can starve other scheduled work."}]}
    ]},
    {id:"events-queue",title:"Events & Event Queue",difficulty:"advanced",time:"25 min",sections:[
      {type:"theory",title:"Event-Driven Architecture",content:"ServiceNow's event system provides <strong>asynchronous decoupling</strong> between the action that fires an event and the handlers that respond.\n\nThe flow:\n1. <strong>Event Registry</strong> (<code>sysevent_register</code>) — defines event names\n2. <strong>gs.eventQueue()</strong> — fires event (inserts into <code>sysevent</code> table)\n3. <strong>Event Worker</strong> — polls sysevent, matches to handlers\n4. <strong>Script Actions</strong> — execute server scripts in response\n5. <strong>Notifications</strong> — send emails as event handlers\n\nEvents are <strong>always asynchronous</strong> with no guaranteed timing."},
      {type:"theory",title:"Why Events Over Direct Calls",content:"<strong>Use events when:</strong>\n• You need async processing (don't block the transaction)\n• Multiple handlers should respond to the same trigger\n• You want to decouple the trigger from the response\n• High-volume processing needs dedicated queue workers\n\n<strong>Use direct calls when:</strong>\n• You need synchronous results\n• The operation must complete before the transaction commits\n• Error handling needs to abort the current operation"},
      {type:"code",title:"Complete Event Pattern",code:"// === Step 1: Fire the event (in a Business Rule) ===\ngs.info('=== Firing Event ===');\ngs.info('Table: incident');\ngs.info('Event: incident.vip.escalated');\ngs.info('');\n\n// gs.eventQueue(eventName, record, parm1, parm2)\ngs.eventQueue('incident.vip.escalated', current,\n    'john.doe@example.com',  // parm1: caller email\n    'INC0010001'             // parm2: incident number\n);\ngs.info('Event queued in sysevent table');\ngs.info('parm1 (email): john.doe@example.com');\ngs.info('parm2 (number): INC0010001');\n\n// === Step 2: Script Action handles it ===\ngs.info('');\ngs.info('=== Script Action Processing ===');\ngs.info('Event worker picks up: incident.vip.escalated');\ngs.info('');\n\n// In the Script Action, event object is available:\n// event.parm1, event.parm2, current (the record)\nvar parm1 = 'john.doe@example.com'; // event.parm1\nvar parm2 = 'INC0010001';           // event.parm2\n\ngs.info('Script Action executing:');\ngs.info('  → Notifying VIP team about ' + parm2);\ngs.info('  → Creating Problem record for pattern analysis');\ngs.info('  → Updating SLA tracking');\ngs.info('');\n\n// Step 3: Could also trigger a Notification\ngs.info('=== Notification Handler ===');\ngs.info('Email sent to: ' + parm1);\ngs.info('Subject: Your incident ' + parm2 + ' has been escalated');"},
      {type:"quiz",questions:[{q:"Where are events stored when fired?",opts:["sys_trigger","sysevent","sys_script_execution","ecc_queue"],ans:1,exp:"gs.eventQueue inserts into the sysevent table for async processing."},{q:"What responds to events?",opts:["Business Rules","Client Scripts","Script Actions and Notifications","UI Policies"],ans:2,exp:"Script Actions (server scripts) and Notifications (emails) are the two event handler types."}]}
    ]},
    {id:"transform-maps",title:"Transform Maps & Import Sets",difficulty:"intermediate",time:"22 min",sections:[
      {type:"theory",title:"Data Import Pipeline",content:"ServiceNow's data import follows a strict pipeline:\n\n1. <strong>Data Source</strong> — defines where data comes from (file, JDBC, REST, etc.)\n2. <strong>Import Set Table</strong> — staging table (<code>u_imp_*</code>) where raw data lands\n3. <strong>Transform Map</strong> — rules for mapping staging fields → target table fields\n4. <strong>Transform Scripts</strong> — custom logic at various stages\n5. <strong>Target Table</strong> — final destination (e.g., <code>cmdb_ci_server</code>)\n\nThe key concept is <strong>coalescing</strong> — matching incoming records to existing records to decide whether to INSERT or UPDATE."},
      {type:"table",title:"Transform Script Types",headers:["Script","When","Use For"],rows:[
        ["onBefore","Before each row transforms","Validate/modify source data, skip bad rows"],
        ["onAfter","After each row transforms","Update related records, trigger workflows"],
        ["onForeignInsert","When a reference field creates a new record","Populate required fields on the auto-created record"],
        ["onReject","When a row fails validation","Log rejection reason, create error record"],
        ["onComplete","After all rows processed","Send summary email, update import log"]
      ]},
      {type:"code",title:"Transform Script Examples",code:"// === onBefore Transform Script ===\n// Runs before each row is mapped to target\ngs.info('=== onBefore: Validate & Clean ===');\n\nvar source_priority = 'HIGH'; // simulated import field\nvar source_name = '  John Doe  ';\n\n// Clean whitespace\nsource_name = source_name.trim();\ngs.info('Cleaned name: \"' + source_name + '\"');\n\n// Map external values to ServiceNow values\nvar priorityMap = {\n    'CRITICAL': '1', 'HIGH': '2', 'MEDIUM': '3', 'LOW': '4'\n};\nvar mapped = priorityMap[source_priority] || '4';\ngs.info('Priority mapped: ' + source_priority + ' → P' + mapped);\n\n// Skip invalid rows\nvar source_email = ''; // empty\nif (gs.nil(source_email)) {\n    gs.warn('SKIP: Missing email — row rejected');\n    // In real transform: ignore = true;\n} else {\n    gs.info('Email valid: ' + source_email);\n}\n\ngs.info('');\n\n// === onAfter Transform Script ===\ngs.info('=== onAfter: Post-Transform ===');\ngs.info('Record created/updated in target table');\ngs.info('→ Triggering assignment lookup');\ngs.info('→ Sending welcome email to new user');\n\ngs.info('');\n\n// === onComplete ===\ngs.info('=== onComplete: Summary ===');\ngs.info('Total rows processed: 150');\ngs.info('Inserted: 120 | Updated: 25 | Rejected: 5');\ngs.info('→ Summary email sent to import.admin@company.com');"},
      {type:"quiz",questions:[{q:"What is coalescing in Transform Maps?",opts:["Merging two tables","Matching import rows to existing records","Compressing data","Validating fields"],ans:1,exp:"Coalescing matches incoming records to existing records to decide INSERT vs UPDATE."},{q:"Which script runs when a reference field auto-creates a record?",opts:["onBefore","onAfter","onForeignInsert","onReject"],ans:2,exp:"onForeignInsert fires when a reference field value doesn't exist and ServiceNow auto-creates the record."}]}
    ]},
    {id:"acls",title:"ACLs with Scripting",difficulty:"advanced",time:"25 min",sections:[
      {type:"theory",title:"Access Control Evaluation",content:"ACLs protect data at three levels: <strong>table</strong>, <strong>field</strong>, and <strong>row</strong>.\n\nEvaluation follows a <strong>most-specific-first</strong> hierarchy:\n\nexact table + exact field → parent table + exact field → exact table + wildcard → parent table + wildcard → <code>*.*</code>\n\nWithin a single ACL, three components use <strong>OR logic</strong> (any one passing grants access):\n• Condition builder\n• Script\n• Requires Role\n\nBetween multiple matching ACLs, <strong>AND logic</strong> — ALL must pass."},
      {type:"table",title:"ACL Operations",headers:["Operation","Controls","Checked When"],rows:[
        ["read","Viewing records/fields","List view, form view, reports, APIs"],
        ["write","Editing records/fields","Form save, API updates, imports"],
        ["create","Creating new records","New record form, insert operations"],
        ["delete","Deleting records","Delete button, deleteRecord(), bulk delete"]
      ]},
      {type:"code",title:"Scripted ACL Patterns",code:"// === Scripted ACL: Restrict by assignment group ===\n// Table: incident.* (read)\n// Script runs for every record access check\n\ngs.info('=== ACL Script: Group-Based Access ===');\n\n// In real ACL, current = the record being checked\nvar userGroupIds = ['ag001', 'ag002']; // simulated user groups\nvar recordGroup = current.getValue('assignment_group');\n\ngs.info('Record assignment_group: ' + recordGroup);\ngs.info('User belongs to: ' + userGroupIds.join(', '));\n\nvar hasAccess = userGroupIds.indexOf(recordGroup) !== -1;\ngs.info('Access granted: ' + hasAccess);\n// In real ACL: answer = hasAccess;\n\ngs.info('');\n\n// === ACL: VIP Incident Restriction ===\ngs.info('=== ACL Script: VIP Restriction ===');\nvar callerId = current.getValue('caller_id');\nvar caller = new GlideRecord('sys_user');\nif (caller.get(callerId) && caller.getValue('vip') === 'true') {\n    // Only users with vip_handler role can see VIP incidents\n    var canSeeVIP = gs.hasRole('admin'); // simplified\n    gs.info('VIP incident detected');\n    gs.info('User has vip_handler role: ' + canSeeVIP);\n    // answer = canSeeVIP;\n} else {\n    gs.info('Non-VIP incident — standard access');\n    // answer = true;\n}\n\ngs.info('');\ngs.info('=== Debugging ACLs ===');\ngs.info('Enable: System Diagnostics → Debug Security Rules');\ngs.info('Check: Security → Access Analyzer (Zurich+)');\ngs.info('Log: /nav_to.do?uri=sys_security_acl_list.do');"},
      {type:"quiz",questions:[{q:"Within a single ACL, how do Condition/Script/Role relate?",opts:["All must pass (AND)","Any one passing grants access (OR)","Script overrides others","Role always wins"],ans:1,exp:"Within ONE ACL, the three components use OR logic — any one passing grants access."},{q:"Between multiple matching ACLs?",opts:["First match wins","OR (any pass)","AND (all must pass)","Last match wins"],ans:2,exp:"Between multiple ACLs matching the same object, AND logic applies — all must pass."}]}
    ]},
    {id:"flow-designer",title:"Flow Designer Scripting",difficulty:"intermediate",time:"22 min",sections:[
      {type:"theory",title:"Flow Designer vs Legacy Workflow",content:"<strong>Flow Designer</strong> is ServiceNow's modern automation engine, replacing legacy Workflow Editor.\n\nKey differences:\n• Flows trigger <strong>AFTER commit</strong> (not at BR order 1000 like Workflows)\n• Actions are <strong>reusable</strong> across multiple flows\n• Built-in <strong>error handling</strong> with try/catch blocks\n• Native <strong>Integration Hub</strong> support for external systems\n• <strong>Subflows</strong> for modular design\n\n<strong>New development should always use Flow Designer.</strong> Legacy Workflows are maintained but no longer the primary investment."},
      {type:"table",title:"Flow Designer Components",headers:["Component","Purpose","Example"],rows:[
        ["Trigger","What starts the flow","Record created, Schedule, Inbound email"],
        ["Action","Single operation step","Create Record, Update Record, Send Email"],
        ["Subflow","Reusable flow module","Approval process, Notification bundle"],
        ["Script Step","Custom server-side code","Complex logic, external API calls"],
        ["Flow Logic","Branching and loops","If/Else, For Each, Do Until"]
      ]},
      {type:"code",title:"Script Step Patterns",code:"// === Flow Designer Script Step ===\n// Available objects: fd_data (flow data), current (trigger record)\n\ngs.info('=== Script Step: Calculate SLA Breach Risk ===');\n\n// Access flow data inputs\nvar incidentId = current.getValue('sys_id');\nvar priority = current.getValue('priority');\ngs.info('Incident: ' + current.getValue('number'));\ngs.info('Priority: P' + priority);\n\n// SLA thresholds (hours)\nvar slaThresholds = { '1': 4, '2': 8, '3': 24, '4': 72 };\nvar threshold = slaThresholds[priority] || 72;\ngs.info('SLA threshold: ' + threshold + ' hours');\n\n// Calculate time since creation (simplified)\nvar hoursOpen = 6; // simulated\nvar riskPct = Math.round((hoursOpen / threshold) * 100);\n\ngs.info('Hours open: ' + hoursOpen);\ngs.info('Breach risk: ' + riskPct + '%');\n\n// Set flow output variables\nif (riskPct >= 80) {\n    gs.warn('→ HIGH RISK — escalation recommended');\n    // fd_data.risk_level = 'high';\n} else if (riskPct >= 50) {\n    gs.info('→ MEDIUM RISK — monitoring');\n    // fd_data.risk_level = 'medium';\n} else {\n    gs.info('→ LOW RISK — on track');\n    // fd_data.risk_level = 'low';\n}\n\n// Output: fd_data.risk_level used by next flow step\ngs.info('');\ngs.info('Script Step output → risk_level available for If/Else branching');"},
      {type:"quiz",questions:[{q:"When do Flow Designer flows trigger?",opts:["At BR order 1000","Before Business Rules","AFTER commit","Before database write"],ans:2,exp:"Flows trigger AFTER commit, which is after all After BRs complete. Different from legacy Workflows."},{q:"What are Subflows?",opts:["Child flows that run in parallel","Reusable flow modules","Flows that run backwards","Error handling flows"],ans:1,exp:"Subflows are reusable flow modules that can be called from multiple parent flows."}]}
    ]}
  ]},

  // ═══════════════════════════════════════════════════════════════════════════
  // ADVANCED TOPICS
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"advanced",title:"Advanced Topics",icon:"◆",children:[
    {id:"scoped-apps",title:"Scoped Applications",difficulty:"advanced",time:"28 min",sections:[
      {type:"theory",title:"Scope Isolation",content:"Each scoped app gets a unique namespace (e.g., <code>x_myco_appname</code>). Scope isolation restricts what code can access:\n\n• GlideRecord queries are limited to <strong>tables within scope</strong> unless explicitly allowed\n• <code>gs.sql()</code> is <strong>unavailable</strong> in scoped apps\n• <code>deleteMultiple()</code> on global tables is <strong>restricted</strong>\n• <code>GlideRecordSecure</code> is recommended over <code>GlideRecord</code>"},
      {type:"table",title:"Cross-Scope Access Methods",headers:["Method","How It Works"],rows:[
        ["Application Access Settings","Per-table CRUD permissions (can read/create/update/delete)"],
        ["sys_scope_privilege","Cross-Scope Privilege Records with Requested/Allowed/Invalidated status"],
        ["Callable Script Includes","Set 'Accessible from: All application scopes'"],
        ["Application Properties","Shared configuration accessible across scopes"]
      ]},
      {type:"code",title:"Scoped App Patterns",code:"// === Scoped App: Access Control ===\ngs.info('=== Scoped Application Patterns ===');\n\n// In a scoped app, GlideRecord respects scope boundaries\nvar gr = new GlideRecord('incident'); // Global table\ngr.addQuery('active', 'true');\ngr.setLimit(3);\ngr.query();\n\ngs.info('Accessing global table from scoped app:');\nwhile (gr.next()) {\n    gs.info('  ' + gr.getValue('number') + ' — ' + gr.getValue('short_description'));\n}\n\ngs.info('');\ngs.info('=== Best Practices ===');\ngs.info('1. Use GlideRecordSecure instead of GlideRecord');\ngs.info('   → Enforces ACLs on every operation');\ngs.info('');\ngs.info('2. Mark Script Includes as \"Accessible from: All\"');\ngs.info('   → Enables cross-scope calling');\ngs.info('');\ngs.info('3. Use Application Properties for config');\ngs.info('   → gs.getProperty(\"x_myco_app.setting\")');\ngs.info('');\ngs.info('4. Never hardcode sys_ids');\ngs.info('   → Use properties or sys_properties for portability');\ngs.info('');\ngs.info('5. Use setWorkflow(false) carefully');\ngs.info('   → May skip other scoped app BRs');"},
      {type:"quiz",questions:[{q:"What is NOT available in scoped apps?",opts:["GlideRecord","gs.info()","gs.sql()","GlideAggregate"],ans:2,exp:"gs.sql() is unavailable in scoped apps — direct SQL access is restricted."},{q:"How to make a Script Include callable from other scopes?",opts:["Set order to 0","Set 'Accessible from: All application scopes'","Add 'global' keyword","Use GlideRecordSecure"],ans:1,exp:"Set the 'Accessible from' field to 'All application scopes' on the Script Include."}]}
    ]},
    {id:"rest-apis",title:"REST APIs",difficulty:"advanced",time:"35 min",sections:[
      {type:"theory",title:"Inbound & Outbound",content:"ServiceNow supports REST in both directions:\n\n<strong>Inbound</strong> (external systems calling ServiceNow):\n• <strong>Table API</strong> (OOTB): <code>/api/now/table/&lt;tablename&gt;</code>\n• <strong>Scripted REST API</strong>: Custom endpoints with full control\n\n<strong>Outbound</strong> (ServiceNow calling external systems):\n• <strong>RESTMessageV2</strong>: Server-side class for HTTP calls\n• <strong>Integration Hub</strong>: No-code/low-code REST actions"},
      {type:"table",title:"Table API Operations",headers:["Method","Endpoint","Action"],rows:[
        ["GET","/api/now/table/incident?sysparm_limit=10","Query incidents"],
        ["GET","/api/now/table/incident/{sys_id}","Get single record"],
        ["POST","/api/now/table/incident","Create incident"],
        ["PUT","/api/now/table/incident/{sys_id}","Replace record"],
        ["PATCH","/api/now/table/incident/{sys_id}","Update fields"],
        ["DELETE","/api/now/table/incident/{sys_id}","Delete record"]
      ]},
      {type:"code",title:"Scripted REST API Endpoint",code:"// === Scripted REST API: /api/x_myco/incidents/active ===\n// Method: GET\n// Produces: application/json\n\ngs.info('=== Scripted REST API: GET /active ===');\ngs.info('');\n\n// In real Scripted REST, request/response objects are available:\n// var query = request.queryParams.get('priority');\n// var limit = request.queryParams.get('limit') || 10;\n\nvar priority = '1'; // simulated query param\nvar limit = 5;\n\nvar results = [];\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\nif (priority) gr.addQuery('priority', priority);\ngr.setLimit(limit);\ngr.orderByDesc('sys_created_on');\ngr.query();\n\nwhile (gr.next()) {\n    results.push({\n        sys_id: gr.getUniqueValue(),\n        number: gr.getValue('number'),\n        short_description: gr.getValue('short_description'),\n        priority: gr.getValue('priority'),\n        state: gr.getValue('state')\n    });\n}\n\nvar responseBody = {\n    result: results,\n    count: results.length,\n    query: { priority: priority, limit: limit }\n};\n\ngs.info('Response:');\ngs.info(JSON.stringify(responseBody, null, 2));\n\ngs.info('');\ngs.info('// In real code:');\ngs.info('// response.setStatus(200);');\ngs.info('// response.setBody(responseBody);');"},
      {type:"code",title:"Outbound REST: RESTMessageV2",code:"// === Outbound REST Call ===\n// Using sn_ws.RESTMessageV2\n\ngs.info('=== Outbound REST: RESTMessageV2 ===');\ngs.info('');\n\n// In real ServiceNow:\n// var rm = new sn_ws.RESTMessageV2('My REST Message', 'POST');\n// rm.setEndpoint('https://api.example.com/webhooks');\n// rm.setRequestHeader('Content-Type', 'application/json');\n// rm.setRequestHeader('Authorization', 'Bearer ' + token);\n\nvar payload = {\n    incident_number: current.getValue('number'),\n    priority: 'P' + current.getValue('priority'),\n    description: current.getValue('short_description'),\n    callback_url: gs.getProperty('glide.servlet.uri') + 'api/now/table/incident/' + current.getUniqueValue()\n};\n\ngs.info('Endpoint: https://api.example.com/webhooks');\ngs.info('Method: POST');\ngs.info('Payload:');\ngs.info(JSON.stringify(payload, null, 2));\n\ngs.info('');\ngs.info('// rm.setRequestBody(JSON.stringify(payload));');\ngs.info('// var response = rm.execute();');\ngs.info('// var httpStatus = response.getStatusCode();');\ngs.info('// var body = response.getBody();');\n\n// Error handling pattern\ngs.info('');\ngs.info('=== Error Handling Pattern ===');\ngs.info('try {');\ngs.info('    var response = rm.execute();');\ngs.info('    if (response.getStatusCode() !== 200) {');\ngs.info('        gs.error(\"REST call failed: \" + response.getStatusCode());');\ngs.info('    }');\ngs.info('} catch(e) {');\ngs.info('    gs.error(\"REST exception: \" + e.getMessage());');\ngs.info('}');"},
      {type:"quiz",questions:[{q:"What's the default Table API endpoint pattern?",opts:["/api/rest/table/","//api/now/table/{tablename}","/api/v1/records/","/rest/now/table/"],ans:1,exp:"The Table API uses /api/now/table/{tablename} with query parameters for filtering."},{q:"What class is used for outbound REST calls?",opts:["GlideHTTPClient","RESTMessageV2 (sn_ws)","GlideAjax","HTTPRequest"],ans:1,exp:"sn_ws.RESTMessageV2 is the server-side class for making outbound HTTP calls."}]}
    ]},
    {id:"atf",title:"Automated Test Framework",difficulty:"advanced",time:"22 min",sections:[
      {type:"theory",title:"Testing in ServiceNow",content:"ATF provides automated testing for ServiceNow customizations. Key concepts:\n\n• <strong>Test</strong> — sequence of test steps executed in order\n• <strong>Test Suite</strong> — collection of tests run together\n• <strong>Quick Start Tests</strong> — OOTB tests for baseline validation\n• <strong>Parameterized Tests</strong> — run the same test with different data\n• <strong>Record Rollback</strong> — auto-cleans up test data after execution\n• <strong>Impersonation</strong> — test with specific user roles"},
      {type:"table",title:"Common Test Step Types",headers:["Step","What It Does"],rows:[
        ["Create a Record","Inserts a new record, stores sys_id for later steps"],
        ["Open a Form","Simulates opening a record form"],
        ["Set Field Values","Updates fields on the form"],
        ["Submit a Form","Triggers save/submit with all associated logic"],
        ["Assert Field Values","Validates field values match expected results"],
        ["Run Server Side Script","Executes custom validation code"],
        ["Impersonate","Switch user context for role testing"]
      ]},
      {type:"code",title:"ATF Server-Side Script Step",code:"// === ATF: Server-Side Validation ===\n// This runs inside a 'Run Server Side Script' test step\n\ngs.info('=== ATF Validation Script ===');\n\n// Step 1: Create test incident\nvar gr = new GlideRecord('incident');\ngr.initialize();\ngr.setValue('short_description', 'ATF Test: VIP Auto-Escalation');\ngr.setValue('caller_id', 'u001'); // John Doe (VIP)\ngr.setValue('priority', '3');\nvar sysId = gr.insert();\ngs.info('Created test incident: ' + sysId);\n\n// Step 2: Verify Business Rule fired\nvar verify = new GlideRecord('incident');\nif (verify.get(sysId)) {\n    var priority = verify.getValue('priority');\n    var assignedTo = verify.getValue('assigned_to');\n    \n    gs.info('After BR execution:');\n    gs.info('  Priority: P' + priority);\n    gs.info('  Assigned: ' + assignedTo);\n    \n    // Assertions\n    if (priority === '1') {\n        gs.info('✓ PASS: VIP auto-escalated to P1');\n    } else {\n        gs.error('✗ FAIL: Expected P1, got P' + priority);\n    }\n    \n    if (assignedTo !== '') {\n        gs.info('✓ PASS: Auto-assigned');\n    } else {\n        gs.error('✗ FAIL: Not auto-assigned');\n    }\n} else {\n    gs.error('✗ FAIL: Could not retrieve test record');\n}\n\ngs.info('');\ngs.info('// In real ATF:');\ngs.info('// steps_passed = (priority === \"1\" && assignedTo !== \"\");');"},
      {type:"quiz",questions:[{q:"What cleans up test data after ATF runs?",opts:["Manual deletion","Record Rollback","Auto-purge schedule","Nothing (data persists)"],ans:1,exp:"ATF's Record Rollback automatically cleans up records created during test execution."},{q:"How do you test different user roles in ATF?",opts:["Create test users","Impersonation step","Role simulation","Mock roles"],ans:1,exp:"Use the Impersonate test step to switch user context and test with specific roles."}]}
    ]},
    {id:"performance",title:"Performance Optimization",difficulty:"advanced",time:"25 min",sections:[
      {type:"theory",title:"The Big Five Anti-Patterns",content:"Most ServiceNow performance issues come from these five patterns:\n\n1. <strong>Nested GlideRecords</strong> — queries inside while loops (N+1 problem)\n2. <strong>getRowCount()</strong> — loads ALL records to count them\n3. <strong>Dot-walking in loops</strong> — hidden nested queries\n4. <strong>Synchronous client GlideRecord</strong> — freezes browser UI\n5. <strong>Non-indexed queries</strong> — full table scans on large tables"},
      {type:"code",title:"Before & After: Every Anti-Pattern",code:"// === Anti-Pattern 1: Nested GlideRecords ===\ngs.info('❌ NESTED GLIDERECORDS');\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nvar q = 0;\nwhile (gr.next()) {\n    var u = new GlideRecord('sys_user');\n    u.get(gr.getValue('caller_id'));\n    q++;\n}\ngs.info('Queries: ' + (q+1));\n\ngs.info('');\ngs.info('✅ FIX: Array Flattening');\nvar ids = [];\ngr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nwhile (gr.next()) {\n    var id = gr.getValue('caller_id');\n    if (id && ids.indexOf(id) === -1) ids.push(id);\n}\nvar ug = new GlideRecord('sys_user');\nug.addQuery('sys_id', 'IN', ids.join(','));\nug.query();\ngs.info('Queries: 2 (always)');\n\ngs.info('');\n\n// === Anti-Pattern 2: getRowCount() ===\ngs.info('❌ getRowCount()');\ngs.info('Loads ALL records into memory just to count');\ngs.info('');\ngs.info('✅ FIX: GlideAggregate');\nvar ga = new GlideAggregate('incident');\nga.addQuery('active', 'true');\nga.addAggregate('COUNT');\nga.query();\nif (ga.next()) gs.info('Count: ' + ga.getAggregate('COUNT'));\ngs.info('Counted at DB level — zero records loaded');\n\ngs.info('');\n\n// === Anti-Pattern 3: No setLimit() ===\ngs.info('❌ Query without limit');\ngs.info('var gr = new GlideRecord(\"incident\");');\ngs.info('gr.query(); // could return 100K+ records!');\ngs.info('');\ngs.info('✅ FIX: Always setLimit()');\ngs.info('gr.setLimit(100); // or use chooseWindow(0, 50)');\n\ngs.info('');\n\n// === Anti-Pattern 4: Hardcoded sys_ids ===\ngs.info('❌ gr.get(\"a1b2c3d4...\") // breaks across instances');\ngs.info('✅ gr.addQuery(\"name\", \"Assignment Group Name\")');"},
      {type:"quiz",questions:[{q:"How to eliminate nested GlideRecords?",opts:["Use GlideRecordSecure","Array flattening with IN operator","Switch to GlideAggregate","Use Before Query BR"],ans:1,exp:"Collect IDs into an array, then query once with the IN operator."},{q:"Why is getRowCount() bad?",opts:["It's deprecated","It loads ALL records into memory","It's slow SQL","It ignores ACLs"],ans:1,exp:"getRowCount() loads every matching record into memory to count them. Use GlideAggregate COUNT instead."}]}
    ]},
    {id:"debugging",title:"Debugging Strategies",difficulty:"intermediate",time:"20 min",sections:[
      {type:"theory",title:"Debugging Toolkit",content:"ServiceNow provides multiple debugging tools:\n\n<strong>Server-side:</strong>\n• <code>gs.info/warn/error/debug</code> — log to System Log\n• <strong>Script Debugger</strong> — breakpoints, step-through, variable inspection\n• <strong>Session Debug</strong> — modules for Business Rules, Security, SQL\n\n<strong>Client-side:</strong>\n• Browser DevTools (F12) — Console, Network, Sources\n• <code>jslog()</code> — logs to browser console\n• <strong>Debug UI Policies</strong> — shows policy evaluation in real-time"},
      {type:"table",title:"Session Debug Modules",headers:["Module","What It Shows"],rows:[
        ["Debug Business Rule","Which BRs fire, in what order, execution time"],
        ["Debug Security Rules","ACL evaluation for every field/table access"],
        ["Debug SQL","Raw SQL generated by GlideRecord queries"],
        ["Debug Log","All gs.log/info/warn/error output"]
      ]},
      {type:"code",title:"Defensive Logging Pattern",code:"// === Production-Safe Debugging ===\ngs.info('=== Debugging an Incident Auto-Assignment ===');\n\n// Use structured logging with context\nvar SCRIPT = 'AutoAssign BR';\n\nfunction log(level, msg) {\n    var prefix = '[' + SCRIPT + '] ';\n    if (level === 'error') gs.error(prefix + msg);\n    else if (level === 'warn') gs.warn(prefix + msg);\n    else gs.info(prefix + msg);\n}\n\nlog('info', 'Starting — incident: ' + current.getValue('number'));\nlog('info', 'Priority: P' + current.getValue('priority'));\nlog('info', 'Category: ' + current.getValue('category'));\n\n// Step-by-step trace\nvar callerId = current.getValue('caller_id');\nlog('info', 'Caller sys_id: ' + callerId);\n\nif (gs.nil(callerId)) {\n    log('warn', 'No caller — skipping auto-assignment');\n} else {\n    var caller = new GlideRecord('sys_user');\n    if (caller.get(callerId)) {\n        log('info', 'Caller found: ' + caller.getValue('first_name') + ' ' + caller.getValue('last_name'));\n        log('info', 'VIP: ' + caller.getValue('vip'));\n        log('info', 'Department: ' + caller.getValue('department'));\n    } else {\n        log('error', 'Caller not found! sys_id: ' + callerId);\n    }\n}\n\ngs.info('');\ngs.info('=== Quick Debug Commands ===');\ngs.info('Enable: System Diagnostics → Session Debug → Business Rule');\ngs.info('View logs: System Logs → All');\ngs.info('SQL trace: Session Debug → Debug SQL');\ngs.info('Clear debug: /nav_to.do?uri=sys_debug.do');"},
      {type:"quiz",questions:[{q:"Which debug module shows raw SQL from GlideRecord?",opts:["Debug Business Rule","Debug Security Rules","Debug SQL","Debug Log"],ans:2,exp:"Debug SQL shows the actual SQL queries generated by GlideRecord operations."},{q:"What client-side function logs to browser console?",opts:["gs.info()","console.log()","jslog()","Both jslog() and console.log()"],ans:3,exp:"Both jslog() and console.log() work on the client side. jslog() is ServiceNow-specific."}]}
    ]},
    {id:"update-sets",title:"Update Sets & Deployment",difficulty:"intermediate",time:"18 min",sections:[
      {type:"theory",title:"Change Management for Config",content:"Update Sets capture configuration changes for migration between instances (Dev → Test → Prod).\n\n<strong>Captured</strong>: Business Rules, Client Scripts, UI Policies, Script Includes, tables, fields, forms, ACLs, workflows, system properties.\n\n<strong>NOT captured</strong>: Data (records in tables), user records, scheduled job run history, attachment content, homepage layouts.\n\nBest practice: <strong>One Update Set per feature/story</strong>. Name convention: <code>PROJ-123 VIP Auto-Escalation</code>."},
      {type:"table",title:"Update Set Lifecycle",headers:["State","Meaning","Action"],rows:[
        ["In Progress","Active, capturing changes","Make your changes"],
        ["Complete","Finalized, ready to move","Mark complete when done"],
        ["Retrieved","Pulled into target instance","Preview to check conflicts"],
        ["Previewed","Conflicts identified","Review and resolve conflicts"],
        ["Committed","Applied to target instance","Changes are live"]
      ]},
      {type:"code",title:"Update Set Best Practices",code:"gs.info('=== Update Set Best Practices ===');\n\ngs.info('1. ONE Update Set per feature');\ngs.info('   ✓ \"PROJ-123 VIP Auto-Escalation\"');\ngs.info('   ✗ \"My Changes March 2026\" (too broad)');\n\ngs.info('');\ngs.info('2. Naming convention:');\ngs.info('   [PROJECT]-[NUMBER] [Description]');\ngs.info('   Example: HR-456 Onboarding Workflow Update');\n\ngs.info('');\ngs.info('3. Before completing:');\ngs.info('   → Review all captured changes');\ngs.info('   → Remove accidental captures');\ngs.info('   → Test in current instance first');\n\ngs.info('');\ngs.info('4. Handling merge conflicts:');\ngs.info('   → Preview BEFORE committing');\ngs.info('   → \"Accept remote\" keeps incoming change');\ngs.info('   → \"Skip remote\" keeps target instance version');\n\ngs.info('');\ngs.info('5. Things NOT in Update Sets:');\ngs.info('   → Data records (use Import Sets)');\ngs.info('   → User accounts (use LDAP/SSO)');\ngs.info('   → Attachments (use scripts)');\ngs.info('   → Homepage layouts');\n\ngs.info('');\ngs.info('6. Fix Scripts for data changes:');\ngs.info('   → Included in Update Sets');\ngs.info('   → Run ONCE per instance');\ngs.info('   → Always make idempotent');\ngs.info('   → Test with setLimit(1) first');"},
      {type:"quiz",questions:[{q:"What is NOT captured in Update Sets?",opts:["Business Rules","Data records in tables","Client Scripts","ACLs"],ans:1,exp:"Data records are NOT captured. Update Sets track configuration changes, not data."},{q:"What should you do before committing an Update Set?",opts:["Delete old ones","Preview to check conflicts","Backup the database","Clear cache"],ans:1,exp:"Always Preview before Committing to identify and resolve conflicts."}]}
    ]}
  ]},

  // ═══════════════════════════════════════════════════════════════════════════
  // PLATFORM INTERNALS
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"internals",title:"Platform Internals",icon:"◎",children:[
    {id:"execution-order",title:"Complete Execution Order",difficulty:"advanced",time:"30 min",sections:[
      {type:"theory",title:"The Full Picture",content:"Understanding execution order is the most important internals knowledge for a ServiceNow developer."},
      {type:"theory",title:"On Form Load",content:"1. <strong>Before Query Business Rules</strong>\n2. <strong>Database read</strong>\n3. <strong>Display Business Rules</strong> (populate g_scratchpad)\n4. <strong>ACL evaluation</strong>\n5. <strong>Form rendered to browser</strong>\n6. <strong>UI Policies (onLoad)</strong> — first client-side\n7. <strong>Client Scripts (onLoad)</strong> — after UI Policies"},
      {type:"theory",title:"On Form Submit",content:"1. <strong>Client Scripts (onSubmit)</strong> — can abort\n2. <strong>UI Policy validations</strong>\n3. <strong>Form data → server</strong>\n4. <strong>Before BRs</strong> (order < 1000)\n5. <strong>Before Engines</strong> (Approval, Assignment)\n6. <strong>Data Policies</strong> at BR order 1000\n7. <strong>Before BRs</strong> (order ≥ 1000)\n8. <strong>DATABASE OPERATION</strong>\n9. <strong>After BRs</strong> (order < 1000)\n10. <strong>After Engines</strong> (Email, SLA)\n11. <strong>After BRs</strong> (order ≥ 1000)\n12. <strong>Async BRs</strong> (queued)\n13. <strong>Flow Designer</strong> (AFTER commit)"},
      {type:"quiz",questions:[{q:"What fires FIRST on submit?",opts:["Before BRs","Data Policies","Client Scripts (onSubmit)","ACLs"],ans:2,exp:"Client Scripts (onSubmit) fire first on the client side."},{q:"When do Flows trigger?",opts:["Before all BRs","At order 1000","After all After BRs","Simultaneously"],ans:2,exp:"Flow Designer triggers AFTER commit."}]}
    ]},
    {id:"acl-evaluation",title:"How ACLs Evaluate",difficulty:"advanced",time:"20 min",sections:[
      {type:"theory",title:"Evaluation Hierarchy",content:"ACLs evaluate in a <strong>most-specific-first</strong> order:\n\n1. exact table + exact field\n2. parent table + exact field\n3. exact table + wildcard field (*)\n4. parent table + wildcard field\n5. <code>*.*</code> (catch-all)\n\n<strong>First GRANT stops evaluation</strong> for that level. Access denied only if ALL applicable ACLs return false.\n\nRow-level ACLs evaluate first, then field-level. If row-level denies, field-level never checks."},
      {type:"table",title:"ACL Logic",headers:["Context","Logic","Meaning"],rows:[
        ["Within ONE ACL","OR","Condition OR Script OR Role — any pass grants"],
        ["Between MULTIPLE ACLs","AND","All matching ACLs must pass"],
        ["Row + Field levels","Sequential","Row denies → field never evaluates"]
      ]},
      {type:"code",title:"ACL Evaluation Trace",code:"gs.info('=== ACL Evaluation Trace: incident.priority (read) ===');\ngs.info('');\n\n// Simulating how ServiceNow evaluates ACLs\ngs.info('Step 1: Find matching ACLs (most specific first)');\ngs.info('  Check: incident.priority (read) → FOUND');\ngs.info('  Check: task.priority (read) → FOUND (parent table)');\ngs.info('  Check: incident.* (read) → FOUND');\ngs.info('  Check: *.* (read) → FOUND');\n\ngs.info('');\ngs.info('Step 2: Evaluate each (AND between multiple)');\n\ngs.info('');\ngs.info('  ACL 1: incident.priority (read)');\ngs.info('    Condition: priority != empty → TRUE');\ngs.info('    Script: (none)');\ngs.info('    Role: itil → user has itil → TRUE');\ngs.info('    Result: PASS (condition OR role = TRUE)');\n\ngs.info('');\ngs.info('  ACL 2: incident.* (read)');\ngs.info('    Condition: active = true → TRUE');\ngs.info('    Script: (none)');\ngs.info('    Role: (none)');\ngs.info('    Result: PASS');\n\ngs.info('');\ngs.info('Step 3: Final verdict');\ngs.info('  ACL 1 PASS AND ACL 2 PASS → ACCESS GRANTED');\n\ngs.info('');\ngs.info('=== Debug Commands ===');\ngs.info('Enable: System Diagnostics → Debug Security Rules');\ngs.info('Tool: Security → Access Analyzer (type table.field)');"},
      {type:"quiz",questions:[{q:"If row-level ACL denies access, what happens to field ACLs?",opts:["They still evaluate","They never evaluate","They override the denial","They run in parallel"],ans:1,exp:"If row-level denies, field-level ACLs never evaluate. The entire record is inaccessible."}]}
    ]},
    {id:"gliderecord-internals",title:"GlideRecord Internals",difficulty:"advanced",time:"22 min",sections:[
      {type:"theory",title:"From JavaScript to SQL",content:"Every GlideRecord operation translates to SQL:\n\n<code>addQuery('active', true)</code> → <code>WHERE active = 1</code>\n<code>addQuery('priority', '<=', '2')</code> → <code>WHERE priority <= 2</code>\n<code>addEncodedQuery('active=true^priority=1')</code> → <code>WHERE active = 1 AND priority = 1</code>\n\nDot-walking generates implicit JOINs: <code>caller_id.email</code> → <code>JOIN sys_user ON ...</code>\n\n<strong>Critical</strong>: Invalid field names are silently ignored, potentially returning ALL records. Enable <code>glide.invalid_query.returns_no_rows</code> to prevent this."},
      {type:"theory",title:"GlideElement Pointer Mechanics",content:"When you access <code>gr.field</code>, you get a <strong>GlideElement</strong> — a Java object pointer that references the current cursor position.\n\nThis pointer <strong>updates automatically</strong> when <code>gr.next()</code> moves the cursor. That's why pushing <code>gr.field</code> into an array during iteration fills the array with the LAST record's values.\n\n<code>getValue()</code> returns a <strong>snapshot string</strong> — it copies the value at that moment, independent of cursor position."},
      {type:"code",title:"SQL Translation Examples",code:"gs.info('=== GlideRecord → SQL Translation ===');\ngs.info('');\n\n// Simple query\ngs.info('gr.addQuery(\"active\", true);');\ngs.info('→ WHERE active = 1');\ngs.info('');\n\n// Operator query\ngs.info('gr.addQuery(\"priority\", \"<=\", \"2\");');\ngs.info('→ WHERE priority <= 2');\ngs.info('');\n\n// Encoded query\ngs.info('gr.addEncodedQuery(\"active=true^priority=1^ORpriority=2\");');\ngs.info('→ WHERE active = 1 AND (priority = 1 OR priority = 2)');\ngs.info('');\n\n// Dot-walking = JOINs\ngs.info('gr.addQuery(\"caller_id.vip\", \"true\");');\ngs.info('→ JOIN sys_user ON incident.caller_id = sys_user.sys_id');\ngs.info('  WHERE sys_user.vip = 1');\ngs.info('');\n\n// IN operator\ngs.info('gr.addQuery(\"sys_id\", \"IN\", \"id1,id2,id3\");');\ngs.info('→ WHERE sys_id IN (\"id1\", \"id2\", \"id3\")');\ngs.info('');\n\n// Actual query execution\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.addQuery('priority', '<=', '2');\ngr.orderBy('priority');\ngr.setLimit(3);\ngr.query();\n\ngs.info('=== Actual Results ===');\nwhile (gr.next()) {\n    gs.info(gr.getValue('number') + ' P' + gr.getValue('priority') + ' — ' + gr.getValue('short_description'));\n}"},
      {type:"quiz",questions:[{q:"What happens with invalid field names in addQuery?",opts:["Error thrown","Returns no records","Silently ignored — ALL records return","Query hangs"],ans:2,exp:"Invalid fields are silently ignored. Enable glide.invalid_query.returns_no_rows for safety."}]}
    ]},
    {id:"caching",title:"Caching Mechanisms",difficulty:"advanced",time:"15 min",sections:[
      {type:"theory",title:"Cache Layers",content:"ServiceNow uses multiple caching layers:\n\n1. <strong>Database Buffer Pool</strong> — MariaDB's InnoDB buffer pool caches hot data pages\n2. <strong>Application Node Cache</strong> — Java heap caches for tables, scripts, ACLs, metadata\n3. <strong>Script Cache</strong> — Compiled Rhino bytecode cached per script\n4. <strong>Reference Field Cache</strong> — Within a transaction, dot-walked references are cached\n5. <strong>Form/UI Cache</strong> — Client-side caching of form layouts and UI policies"},
      {type:"table",title:"Cache Management",headers:["Action","How","When"],rows:[
        ["View cache stats","xmlstats.do?include=cache","Diagnosing cache issues"],
        ["Flush all caches","cache.do","After major config changes"],
        ["Flush specific cache","sys_cache_flush.do","Targeted cache refresh"],
        ["Script cache clear","Automatic on save","When saving a script"]
      ]},
      {type:"code",title:"Caching Impact on Code",code:"gs.info('=== Caching Implications for Developers ===');\ngs.info('');\n\n// Dot-walking is cached within a transaction\ngs.info('1. Reference caching within transaction:');\ngs.info('   First call: gr.caller_id.email → DB query');\ngs.info('   Second call: gr.caller_id.email → CACHED (no query)');\ngs.info('   But in a NEW transaction → DB query again');\n\ngs.info('');\ngs.info('2. Script caching:');\ngs.info('   Scripts compile to Java bytecode on first execution');\ngs.info('   Subsequent calls use cached bytecode');\ngs.info('   Saving a script invalidates its cache entry');\n\ngs.info('');\ngs.info('3. System property caching:');\ngs.info('   gs.getProperty() reads from cache, not DB');\ngs.info('   gs.setProperty() updates DB + invalidates cache');\ngs.info('   Other nodes may have stale values briefly');\n\ngs.info('');\ngs.info('4. When to flush caches:');\ngs.info('   → After direct DB updates (Fix Scripts)');\ngs.info('   → When UI changes don\\'t appear');\ngs.info('   → After Update Set commit');\ngs.info('   → URL: /cache.do');"},
      {type:"quiz",questions:[{q:"Where do you view cache statistics?",opts:["stats.do","xmlstats.do?include=cache","cache.do","sys_properties.do"],ans:1,exp:"xmlstats.do?include=cache shows detailed cache statistics for the application node."}]}
    ]}
  ]},

  // ═══════════════════════════════════════════════════════════════════════════
  // PRACTICE & INTERVIEW
  // ═══════════════════════════════════════════════════════════════════════════
  {id:"practice",title:"Practice & Interview",icon:"★",children:[
    {id:"beginner-challenges",title:"Beginner Challenges",difficulty:"beginner",time:"30 min",sections:[
      {type:"theory",title:"5 Hands-On Challenges",content:"Solve these using the playground below. Each challenge tests a core ServiceNow concept.\n\n<strong>Challenge 1:</strong> Query all active P1 incidents and log their numbers and descriptions.\n\n<strong>Challenge 2:</strong> Find the user with email 'jane.smith@example.com' and log all their details.\n\n<strong>Challenge 3:</strong> Count active incidents per priority level using GlideAggregate.\n\n<strong>Challenge 4:</strong> Create a new incident for user 'bob.wilson' with priority 3, category 'software'.\n\n<strong>Challenge 5:</strong> Find all VIP users and log their names and titles."},
      {type:"code",title:"Challenge Playground",code:"// ╔══════════════════════════════════════════════╗\n// ║  BEGINNER CHALLENGES — Write your code below  ║\n// ╚══════════════════════════════════════════════╝\n// Available tables: incident, sys_user, cmdb_ci, problem, change_request\n// Available APIs: GlideRecord, GlideAggregate, gs\n\n// Challenge 1: Query active P1 incidents\ngs.info('=== Challenge 1: Active P1 Incidents ===');\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.addQuery('priority', '1');\ngr.query();\nwhile (gr.next()) {\n    gs.info(gr.getValue('number') + ' — ' + gr.getValue('short_description'));\n}\n\n// Challenge 2: Find user by email\ngs.info('');\ngs.info('=== Challenge 2: Find User ===');\n// Your code here...\n\n// Challenge 3: Count by priority\ngs.info('');\ngs.info('=== Challenge 3: Count by Priority ===');\n// Your code here...\n\n// Challenge 4: Create incident\ngs.info('');\ngs.info('=== Challenge 4: Create Incident ===');\n// Your code here...\n\n// Challenge 5: VIP users\ngs.info('');\ngs.info('=== Challenge 5: VIP Users ===');\n// Your code here..."}
    ]},
    {id:"intermediate-challenges",title:"Intermediate Challenges",difficulty:"intermediate",time:"45 min",sections:[
      {type:"theory",title:"7 Real-World Scenarios",content:"<strong>Challenge 1:</strong> Write a Script Include method that returns all incidents assigned to a user, grouped by priority.\n\n<strong>Challenge 2:</strong> Simulate a Before BR that prevents closing an incident if the caller is VIP and no resolution notes exist.\n\n<strong>Challenge 3:</strong> Use array flattening to get all unique callers for active incidents and log their email addresses — using only 2 queries.\n\n<strong>Challenge 4:</strong> Write an After BR that fires an event when an incident is escalated (priority changes to a lower number).\n\n<strong>Challenge 5:</strong> Build a GlideAggregate query that shows incident count by category, sorted highest to lowest.\n\n<strong>Challenge 6:</strong> Create a utility function that safely updates a record without triggering Business Rules or updating sys fields.\n\n<strong>Challenge 7:</strong> Write a function that detects infinite loop risk by checking if current and previous have the same values for key fields."},
      {type:"code",title:"Challenge Playground",code:"// ╔══════════════════════════════════════════════════╗\n// ║  INTERMEDIATE CHALLENGES — Pick any to solve     ║\n// ╚══════════════════════════════════════════════════╝\n\n// Challenge 3: Array Flattening (2 queries only!)\ngs.info('=== Challenge 3: Array Flattening ===');\n\nvar callerIds = [];\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nwhile (gr.next()) {\n    var cid = gr.getValue('caller_id');\n    if (cid && callerIds.indexOf(cid) === -1) callerIds.push(cid);\n}\ngs.info('Unique callers: ' + callerIds.length);\n\nvar userGr = new GlideRecord('sys_user');\nuserGr.addQuery('sys_id', 'IN', callerIds.join(','));\nuserGr.query();\nwhile (userGr.next()) {\n    gs.info(userGr.getValue('first_name') + ' ' + userGr.getValue('last_name') + ' → ' + userGr.getValue('email'));\n}\n\ngs.info('Total queries: 2 ✓');\n\n// Try the other challenges below!\ngs.info('');\ngs.info('=== Challenge 6: Silent Update Utility ===');\nfunction silentUpdate(table, sysId, fields) {\n    var gr = new GlideRecord(table);\n    if (gr.get(sysId)) {\n        for (var field in fields) {\n            gr.setValue(field, fields[field]);\n        }\n        gr.setWorkflow(false);\n        gr.autoSysFields(false);\n        gr.update();\n        gs.info('Silently updated: ' + table + ' / ' + sysId);\n    }\n}\n\nsilentUpdate('incident', 'a1b2c3d4e5f6', {\n    description: 'Updated by automation',\n    state: '2'\n});"}
    ]},
    {id:"advanced-challenges",title:"Advanced Challenges",difficulty:"advanced",time:"60 min",sections:[
      {type:"theory",title:"8 Architecture-Level Challenges",content:"<strong>Challenge 1:</strong> Design a Scripted REST API endpoint that returns paginated results with proper error handling.\n\n<strong>Challenge 2:</strong> Refactor a nested GlideRecord query (3 levels deep) into flat queries using array flattening.\n\n<strong>Challenge 3:</strong> Write a Before Query BR that implements row-level security — users can only see incidents from their department.\n\n<strong>Challenge 4:</strong> Build an event-based processing pattern for high-volume incident creation.\n\n<strong>Challenge 5:</strong> Write a Script Include that detects circular references in a management hierarchy.\n\n<strong>Challenge 6:</strong> Create an idempotent Fix Script that migrates data between two tables.\n\n<strong>Challenge 7:</strong> Design an ATF test suite for a VIP auto-escalation Business Rule.\n\n<strong>Challenge 8:</strong> Optimize a slow report query by analyzing and refactoring the encoded query."},
      {type:"code",title:"Challenge: Scripted REST with Pagination",code:"// === Advanced Challenge 1: Paginated REST API ===\n\nfunction handleGetRequest(queryPriority, page, pageSize) {\n    page = page || 1;\n    pageSize = pageSize || 10;\n    var offset = (page - 1) * pageSize;\n    \n    // Get total count first\n    var ga = new GlideAggregate('incident');\n    ga.addQuery('active', 'true');\n    if (queryPriority) ga.addQuery('priority', queryPriority);\n    ga.addAggregate('COUNT');\n    ga.query();\n    var total = 0;\n    if (ga.next()) total = parseInt(ga.getAggregate('COUNT'));\n    \n    // Get page of results\n    var results = [];\n    var gr = new GlideRecord('incident');\n    gr.addQuery('active', 'true');\n    if (queryPriority) gr.addQuery('priority', queryPriority);\n    gr.orderByDesc('sys_created_on');\n    gr.chooseWindow(offset, offset + pageSize);\n    gr.query();\n    \n    while (gr.next()) {\n        results.push({\n            sys_id: gr.getUniqueValue(),\n            number: gr.getValue('number'),\n            short_description: gr.getValue('short_description'),\n            priority: gr.getValue('priority')\n        });\n    }\n    \n    return {\n        result: results,\n        pagination: {\n            page: page,\n            page_size: pageSize,\n            total: total,\n            total_pages: Math.ceil(total / pageSize),\n            has_next: page * pageSize < total\n        }\n    };\n}\n\n// Test it\nvar response = handleGetRequest(null, 1, 3);\ngs.info(JSON.stringify(response, null, 2));"}
    ]},
    {id:"interview-questions",title:"Interview Questions",difficulty:"intermediate",time:"40 min",sections:[
      {type:"theory",title:"40+ Curated Questions by Topic",content:"These questions are compiled from real ServiceNow developer interviews at major companies. Each includes the expected answer depth.\n\n<strong>Platform Architecture (5)</strong>\n1. Explain ServiceNow's multi-instance architecture vs multi-tenant.\n2. What is the Glide stack? How does a request flow through the system?\n3. What is a MID Server and when do you need one?\n4. Explain table inheritance with a real example.\n5. What's the difference between global and scoped applications?"},
      {type:"theory",title:"Client-Side Questions (8)",content:"6. Name the four Client Script types and when each fires.\n7. What's the execution order: UI Policies vs Client Scripts?\n8. Explain the complete GlideAjax flow (client + server).\n9. Why should you never use synchronous GlideRecord on the client?\n10. What is g_scratchpad and how does it work?\n11. Explain setValue on a reference field — what's the gotcha?\n12. How do you pass data from server to client without GlideAjax?\n13. What's the difference between setVisible and setDisplay?"},
      {type:"theory",title:"Server-Side Questions (10)",content:"14. List all Business Rule types and when to use each.\n15. What is the complete execution order on form submit?\n16. What happens at BR order 1000?\n17. How do you prevent infinite loops in Business Rules?\n18. Explain the Script Include class prototype pattern.\n19. What is the difference between GlideRecord and GlideRecordSecure?\n20. How does gs.eventQueue work? What are Script Actions?\n21. What is the GlideElement trap? How do you avoid it?\n22. Explain encoded queries — what operators are available?\n23. When should you use GlideAggregate over GlideRecord?"},
      {type:"theory",title:"Security & Performance Questions (8)",content:"24. How do ACLs evaluate? Explain the specificity hierarchy.\n25. What's the difference between ACL and UI Policy for security?\n26. How would you debug an ACL that's incorrectly denying access?\n27. What is the #1 GlideRecord performance anti-pattern?\n28. How does array flattening solve nested GlideRecords?\n29. Why is getRowCount() bad? What's the alternative?\n30. How do you identify slow scripts in ServiceNow?\n31. What performance tools does ServiceNow provide?"},
      {type:"theory",title:"Integration & Advanced Questions (9)",content:"32. Explain inbound vs outbound REST in ServiceNow.\n33. How do you create a Scripted REST API? Walk through the process.\n34. What authentication methods does ServiceNow REST support?\n35. What is Integration Hub? When would you use it vs REST?\n36. Explain Update Set best practices for team development.\n37. How does domain separation affect scripting?\n38. What is ATF? How do you write effective tests?\n39. Compare Flow Designer vs legacy Workflow — when to use each?\n40. Design question: How would you build a custom app with approval workflow, REST integration, and scheduled cleanup?"},
      {type:"code",title:"Practice: Answer Key Concepts",code:"// Quick reference for the most-asked interview questions\n\ngs.info('=== Q14: Business Rule Types ===');\ngs.info('Before: Modify current before save');\ngs.info('After: Update related records, fire events');\ngs.info('Async: Long ops (previous is NULL!)');\ngs.info('Display: Populate g_scratchpad for client');\ngs.info('Before Query: Filter records programmatically');\n\ngs.info('');\ngs.info('=== Q15: Execution Order on Submit ===');\ngs.info('1. Client onSubmit → 2. UI Policy validation →');\ngs.info('3. Server: Before BRs (<1000) → 4. Engines (1000) →');\ngs.info('5. Before BRs (≥1000) → 6. DB WRITE →');\ngs.info('7. After BRs (<1000) → 8. After Engines →');\ngs.info('9. After BRs (≥1000) → 10. Async BRs → 11. Flows');\n\ngs.info('');\ngs.info('=== Q27: #1 Performance Anti-Pattern ===');\ngs.info('Nested GlideRecords (N+1 problem)');\ngs.info('Fix: Array flattening with IN operator');\nvar ids = [];\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.query();\nwhile (gr.next()) {\n    var id = gr.getValue('caller_id');\n    if (id && ids.indexOf(id) === -1) ids.push(id);\n}\ngs.info('Collected ' + ids.length + ' unique IDs in pass 1');\ngs.info('Single IN query replaces ' + ids.length + ' individual queries');"}
    ]},
    {id:"anti-patterns",title:"Patterns & Anti-Patterns",difficulty:"intermediate",time:"25 min",sections:[
      {type:"theory",title:"The Critical Do's and Don'ts",content:"These patterns separate junior from senior ServiceNow developers. Each anti-pattern includes the correct alternative."},
      {type:"table",title:"Anti-Pattern Quick Reference",headers:["❌ Anti-Pattern","✅ Correct Pattern","Why"],rows:[
        ["Nested GlideRecords","Array flattening + IN operator","N+1 queries → always 2 queries"],
        ["getRowCount()","GlideAggregate COUNT","Loads all records vs DB-level count"],
        ["gr.field in arrays","gr.getValue('field')","GlideElement pointer vs string snapshot"],
        ["Sync client GlideRecord","GlideAjax async","Browser freeze vs async callback"],
        ["Hardcoded sys_ids","Properties or encoded queries","Breaks across instances"],
        ["current.update() in Before BR","Just set values on current","Triggers another BR cycle"],
        ["Global Client Scripts","Table-specific scripts","Loads on EVERY form"],
        ["Dot-walking in loops","Cache value before loop","Hidden nested query per iteration"],
        ["No setLimit()","Always setLimit() for safety","Prevents runaway queries"],
        ["gs.log() (deprecated)","gs.info/warn/error","Proper log levels + filtering"]
      ]},
      {type:"code",title:"Essential Patterns Library",code:"// === Pattern 1: Defensive GlideRecord ===\ngs.info('=== Pattern 1: Defensive Query ===');\nvar gr = new GlideRecord('incident');\ngr.addQuery('active', 'true');\ngr.addQuery('priority', '1');\ngr.setLimit(100); // Always limit!\ngr.orderByDesc('sys_created_on');\ngr.query();\n\nvar results = [];\nwhile (gr.next()) {\n    results.push(gr.getValue('number')); // getValue, not gr.field\n}\ngs.info('Found: ' + results.length);\n\n// === Pattern 2: Silent Update ===\ngs.info('');\ngs.info('=== Pattern 2: Silent Update ===');\nvar update = new GlideRecord('incident');\nif (update.get('b2c3d4e5f6g7')) {\n    update.setValue('state', '2');\n    update.setWorkflow(false);    // No BRs\n    update.autoSysFields(false);  // No sys_updated_on change\n    update.update();\n    gs.info('Updated without triggering BRs');\n}\n\n// === Pattern 3: Event-Based Decoupling ===\ngs.info('');\ngs.info('=== Pattern 3: Event Decoupling ===');\ngs.info('Instead of heavy logic in After BR:');\ngs.info('  gs.eventQueue(\"incident.escalated\", current, p1, p2)');\ngs.info('Then handle in Script Action (async, non-blocking)');\n\n// === Pattern 4: Check Before Act ===\ngs.info('');\ngs.info('=== Pattern 4: Change Detection ===');\nvar curr = current.getValue('state');\nvar prev = previous.getValue('state');\nif (curr !== prev) {\n    gs.info('State changed: ' + prev + ' → ' + curr);\n    gs.info('Safe to proceed with post-change logic');\n} else {\n    gs.info('No change — skipping (prevents recursion)');\n}"},
      {type:"quiz",questions:[{q:"Why never use current.update() in a Before BR?",opts:["It's deprecated","It triggers another Business Rule cycle","It doesn't save","It skips ACLs"],ans:1,exp:"current.update() in a Before BR triggers another round of Business Rules, causing potential infinite loops."},{q:"Why avoid global Client Scripts?",opts:["They don't work","They load on EVERY form in the system","They can't access g_form","They run on the server"],ans:1,exp:"Global Client Scripts load on every form in the system, degrading performance for all users."}]}
    ]}
  ]}
];
